INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (1, N'云mall-java后端开发工程师-电商武汉', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责电商核心系统从需求分析、方案设计到开发上线的完整交付； 2.参与电商业务模型和平台架构设计，支撑复杂交易场景及业务持续发展； 3.负责系统性能、稳定性和线上问题治理，推动系统持续演进； 4.在研发过程中合理使用 AI，提高研发效率和交付质量，并对最终结果负责； 5.与产品、前端、测试及相关团队协作，将业务规则、技术约束和工程经验转化为 AI 可理解、可验证、可复用的项目知识和研发工作流； 6.该岗位签约主体为云智。
