INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (3, N'微信秒剪-大模型后端研发工程师广州', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责多模态内容理解与生成技术在视频剪辑、内容理解及内容生成等业务场景中的研发与落地； 2.负责多模态模型的工程化部署与服务建设，包括推理链路优化、性能调优、模型调度、监控告警及稳定性治理； 3.参与多模态生成式推荐相关研发，建设覆盖离线、近线和在线场景的数据处理与特征链路； 4.构建多模态相关后台服务性能指标，建设面向 Agent 开发的测试 Harness、自动化评测和回归机制，引入测试驱动开发，保障服务质量与稳定性。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (4, N'腾讯云研发效能-后端开发工程师西安', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责项目团队CICD流水线建设和日常维护； 2.支持项目代码管理、构建管理、版本发布规范化建设； 3.负责项目团队研发过程改进、研效提升方案制定和落地实践。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (5, N'营销与交易产品部-云mall高级Java后端开发工程师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.岗位职责； 2.负责电商核心系统从需求分析、方案设计到开发上线的完整交付； 3.参与电商业务模型和平台架构设计，支撑复杂交易场景及业务持续发展； 4.负责系统性能、稳定性和线上问题治理，推动系统持续演进； 5.在研发过程中合理使用 AI，提高研发效率和交付质量，并对最终结果负责； 6.与产品、前端、测试及相关团队协作，将业务规则、技术约束和工程经验转化为 AI 可理解、可验证、可复用的项目知识和研发工作流。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (6, N'《无畏契约》-前端开发工程师-（AI & 创新互动方向）深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.多端体验与AI营销迭代：负责线上游戏官网、活动页、小程序及 AI 驱动的个性化营销/互动模块 的开发与维护，保障跨设备（PC/移动）流畅度与体验一致性； 2.线下沉浸式与AIGC互动开发：负责营销及电竞等线下场景的创新体验开发，结合 AIGC、视觉互动及智能音/视频 等前沿技术提升玩家沉浸感； 3.桌面端生态：负责 PC 客户端场景页面（含基于 Electron 开发的内嵌页面）的前端开发与长期迭代维护； 4.AI 赋能工程化体系：推进前端工程化建设，构建高效组件库与自动化工具，积极引入/探索 AI 工具链（如 Code Copilot、AI Code Review 等）提升团队全流程开发效率与代码质量； 5.跨团队紧密协作：与后端、设计、产品及 AI 工程/算法团队 紧密协作，完成接口对接、数据交互逻辑实现及创新需求的敏捷落地； 6.性能与稳定性保障：持续优化用户端加载速度与响应效率，解决多终端兼容性问题，保障高并发场景下的系统高可用。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (7, N'混元Agent评测Infra工程师（北京/上海/深圳）北京', 1, N'学历不限', N'社招', N'IEC   ', N'1.构建评测运行底座：统筹沙盒环境、依赖管理、网络访问、并发调度等关键能力建设，保障大规模评测在生产环境下的稳定、可复现与高效运行； 2.保障评测质量与可观测性：从 Harness 与打分逻辑出发，确保平台化改造后评测结果的准确可信，并建立完善的诊断与问题归因能力； 3.衔接算法与工程：深入理解各 Benchmark 所考察的模型能力维度，作为算法与平台之间的技术桥梁，推动评测需求高质量落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (8, N'Technology Platform-游戏机器学习研究工程师深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责机器学习/AI在游戏研发过程的应用落地； 2.结合计算机图形学知识，参与建模、渲染、动画、特效、UI、物理、AIGC等相关工作； 3.与策划、美术、运营、程序等同学做需求沟通； 4.跟进行业AI新技术、图形学前沿应用，落地到游戏项目实际业务中。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (9, N'QQ飞车端游-服务器后台开发工程师-新星引力计划深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责游戏服务器后端架构设计与核心功能开发； 2.实现高并发、低延迟的游戏逻辑处理与数据同步方案； 3.与策划、客户端开发团队紧密协作，确保系统设计符合游戏需求； 4.优化服务器性能与资源利用率，保障大规模玩家在线体验； 5.持续迭代维护现有系统，快速定位并解决线上技术问题。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (10, N'WeTalk-大模型应用研发工程师-（Agent Harness）广州', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责 WeTalk Agent Harness 的设计与开发，包括 Agent Loop、编排和运行环境等核心能力； 2.建设 Context Engineering 能力，包括上下文压缩、Skill、跨会话 Memory、检索和长任务状态管理； 3.搭建 Agent 评测体系，通过评测数据、运行 Trace 和用户反馈定位问题，推动模型、Prompt、Context、Tool 等策略持续优化； 4.参与 WeTalk AI 能力的探索与落地，并将业务实践沉淀为稳定、通用的工程能力。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (11, N'Marvis高级前端开发工程师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责 Marvis AI Agent 产品桌面端的架构设计与开发工作； 2.负责独立模块，与各方紧密协作，参与需求分析、方案设计、开发交付与迭代优化，推动项目落地； 3.持续优化桌面端性能，提升应用响应速度和稳定性，确保良好的用户体验； 4.关注前端和 AI 技术发展趋势，结合业务场景进行落地实践，提升开发效率和产品质量。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (12, N'微信小程序-前端开发工程师-开发者方向广州', 1, N'学历不限', N'社招', N'IEC   ', N'1. 负责小程序开发者生态 & 服务商相关项目的前端开发工作 2. 负责 AI 技术与小程序开发生态结合的相关工作，通过 AI 给开发者和商家提效、赋能 3. 参与技术基建，持续优化研发效能，提升团队工程效率
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (13, N'微信支付-全栈开发工程师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责规划与构建高性能、高可用的前端智能研发效能平台，保障平台流畅运行与优质体验，适配多终端使用场景； 2.设计与维护平台前端架构，提供工业级开发工具能力，覆盖代码补全、语法校验、AI辅助编码、实时调试等核心研发场景； 3.持续优化平台交互体验与运行性能，定位并解决使用过程中的前端技术问题，提升编码效率与工具稳定性； 4.参与需求分析、技术选型、系统设计与开发实施，推动AI能力与前端工程工具深度融合及方案落地； 5.与跨团队（AI算法、后端、产品）高效协作，洞察开发者真实使用需求，提供技术支持，确保平台满足不同场景下的研发诉求； 6.持续跟踪前端技术与AI研发工具的演进趋势，引入新技术与最佳实践，提升平台的先进性与市场竞争力。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (14, N'智能体-桌面端开发负责人-WorkBuddy深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.带领前端团队负责 WorkBuddy 桌面端（Electron）核心业务功能的设计与开发，基于现代 Web 技术栈将产品需求高质量落地为稳定、流畅的桌面端用户体验； 2.负责前端业务的领域建模与架构抽象，将复杂产品诉求转化为清晰的前端分层、模块边界与可扩展的实现方案，保障代码可维护性； 3.主导跨平台（Windows/macOS/Linux 及信创）前端功能的适配与兼容处理，保障各系统在 UI 渲染、交互体验上的一致性与完整性； 4.与产品、设计、AI Agent 团队紧密协作，承接复杂业务场景（Agent 任务执行、本地文件操作、多任务并行）的前端状态管理与交互实现； 5.持续优化桌面端前端性能（如首屏加载、渲染帧率、内存占用），打磨交互细节，提升用户在日常办公与开发场景下的使用流畅度； 6.沉淀前端业务组件库与开发规范，推动跨团队前端能力复用，拉通桌面端前端技术标准与最佳实践。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (15, N'混元大模型平台全栈开发工程师（深圳/北京）深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.一站式平台前端架构与全栈研发：负责混元大模型一站式平台的前后端全链路研发工作，覆盖模型训练、效果评测、服务部署、数据管理、权限管理等核心模块的建设与迭代。主导平台前端架构设计，构建高复用、可配置、可扩展的组件化与模板化体系，持续提升平台研发效率与用户体验； 2.复杂交互与可视化能力建设：负责大模型训练监控、评测看板、任务流编排、模型对比等复杂交互页面的开发与优化。设计并实现与大模型训练、推理、评测等后端服务的高效通信方案，处理流式数据、实时状态同步等高并发场景； 3.全栈通用能力沉淀与工程化升级：沉淀组件库、公共模块及工程化能力，推动平台能力标准化和规模化复用。参与平台架构设计与通用能力建设，提升系统扩展性、复用性和稳定性。关注AIGC、大模型工程化前沿技术，持续优化平台技术方案与研发效能； 4.跨团队协同与项目落地：与算法研发、AI工程、产品经理等团队深度协作，拆解复杂技术诉求，独立完成核心模块设计、开发与迭代，具备极强的项目Owner意识与自驱力。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (16, N'AI技术型产品运营深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.智能社群管理（万人级）： 负责搭建与维护社群运营 Agent，实现万人社群的自动化答疑、活跃引导及违规监控，确保社群 7x24 小时高质量运转； 2.内容生产与宣发提效： 开发专门针对业务场景的内容宣发智能体（Content Agent），通过 AI 辅助产出高质量文案、海报及视频脚本，并实现多平台的一键/自动化分发； 3.前端快速迭代： 负责运营相关 H5、活动网页及产品前端界面的设计与开发。要求能够利用低代码或现代前端框架（如 Next.js/Tailwind）进行“最小化可行产品 (MVP)”的快速产出与测试； 4.流程自动化： 持续探索 AI 工具链（如 n8n, Make, Zapier），消除运营过程中的重复劳动。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (17, N'微信小店-全栈开发工程师-交易基建方向广州', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责电商相关基建的开发工作，涵盖客服、售后、物流等模块； 2.主动推动团队技术基建的持续迭代和优化，完善团队AI Agent基建，提升团队研效。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (18, N'芯片设计工程师上海', 1, N'学历不限', N'社招', N'RIE   ', N'1.负责芯片的详细设计、实现及综合等设计工作； 2.负责芯片的性能分析及优化； 3.支撑验证团队完成UT/IT/ST验证计划的制定和执行、覆盖率收集、原型验证问题定位； 4.支撑后端团队完成floorplan, 网表交付交付质量把控。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (19, N'腾讯AI协作工具-全栈开发工程师（编辑器）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.参与腾讯文档各品类核心引擎研发，包括编辑、排版、计算、渲染、交互及协同等能力； 2.负责 Office OOXML、PDF 等文档格式的解析、生成、转换及高保真兼容； 3.参与前端引擎、Node.js 服务及业务后台研发，持续优化系统性能、稳定性和工程质量； 4.推动引擎能力在文档编辑、格式转换、内容解析、跨端应用等业务场景落地； 5.负责 AI Agent 相关能力开发与调优，探索智能生成、内容理解和人机协同编辑； 6.建设上下文工程、Harness / Loop Engineering、工具调用、评测及可观测等 AI 工程体系； 7.参与系统设计和核心技术难点攻关，推动新技术落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (20, N'AI测试架构师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责AI金融测试工具及平台的整体架构设计与迭代优化，打造高可用、可扩展的AI赋能测试基础设施； 2.推动大模型、Agent及RAG技术在金融AI集成测试、高频接口测试、测试用例智能生成等核心场景的深度落地； 3.建立模型效果评测与优化飞轮，参与模型上下文设计、Prompt工程及推理加速，推动大模型在测试场景下的效果持续迭代； 4.关注AI领域前沿技术，开展AI测试知识图谱建设、缺陷根因分析、AI智能压测等前瞻性场景的技术攻坚与应用探索。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (21, N'腾讯云-音视频测试工程师（测试agent开发方向）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责音视频产品全维度测试，包括核心功能、性能、高可用、弱网抗丢包、音视频效果（画质/音质）、兼容性、环境建设等，主导专项质量问题的排查与复盘； 2.主导音视频测试新技术调研与落地，依托 AI Agent 构建智能化测试工作流，探索测试用例生成、缺陷定位、结果研判等场景的智能化提效； 3.搭建覆盖音视频理解、图像/视频生成、语音生成等能力的评测体系与数据集，产出高效、可信的评测结论；对接 MaaS / TokenHub 模型网关，完成多模型接入，验证协议转换、媒体转码、参数适配、异常降级、性能限频等能力； 4.设计并开发音视频自动化测试框架、专项测试工具与数据统计能力，持续沉淀可复用的测试资产； 5.参与 CI/CD 流水线搭建与优化，落地自动化测试门禁与线上质量监控门禁，推动质量左移与提效。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (22, N'企业微信-测试开发工程师-AI测试提效方向广州', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责企业微信协作应用相关的测试开发工作，包括测试计划设计、用例开发、测试执行、bug 分析及跟踪； 2.开发与维护自动化测试框架及用例转化运行，提升测试效率和质量； 3.探索并落地自动化评测与模型缺陷归因机制，深入分析测试与评测过程中的问题，定位根本原因，推动问题解决； 4.持续优化测试与评测流程、方法和工具，提升团队测试效能； 5.参与技术攻关，解决复杂测试与评测问题，积极推动测试技术创新。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (23, N'AI芯片软件测试开发工程师-AI软件测试方向深圳', 1, N'学历不限', N'社招', N'RIE   ', N'1.负责芯片软件栈（算子库、图编译器、运行时、推理框架）的测试工作，包括测试策略制定、用例设计开发、测试执行与质量评估； 2.负责芯片软件栈测试体系建设：引入业界成熟的分层测试、精度基准、性能基准与回归体系方法论，能结合自研芯片架构特点落地； 3.设计并开发自动化测试框架和工具链，覆盖算子精度验证、模型推理正确性、性能与稳定性评测； 4.分析测试中发现的问题，跨栈定位根因（算子实现/编译器优化/运行时/驱动），推动问题闭环； 5.持续优化测试流程、方法和工具，提升团队测试效能。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (24, N'腾讯云-测试效能高级工程师（AI测试智能化方向）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责存储或终端安全产品的全流程质量效能体系建设； 2.搭建完善的精准测试质量保障体系，识别研发全链路质量风险，主导质量门禁落地，推动质量优化前置； 3.主导建设研发测试全流程效能，迭代CI/CD全链路校验机制，搭建自动化测试体系与效能工具； 4.负责测试智能化AI提效建设，落地测试Agent与多智能体编排体系； 5.建立AI测试能力评测，评估优化AI工具与Agent效果，沉淀落地最佳实践，解决传统测试低效痛点。
