INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (26, N'AI Agent测试开发工程师深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责安全系统的测试工作，包括测试计划设计、用例开发、测试执行、缺陷分析及跟踪； 2.参与安全测试场景下 AI Agent 协作能力与评测体系的落地，支撑用例生成、代码转换、缺陷修复、自评估等能力在实际测试中的应用； 3.跟进线上问题并参与复盘，输出质量报告，推动研发流程与质量体系优化； 4.持续优化测试流程、方法和工具，提升团队测试效能。
