INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (28, N'魔方技术中心-游戏测试开发工程师-客户端性能测试方向深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责游戏客户端性能测试工作，包括测试方案设计和执行、性能问题分析、流程和自动化建设等； 2.负责开发、优化客户端性能测试相关的执行或分析类工具，提升测试质量和效率； 3.负责收集和分析业务性能测试需求，探索更多的测试方法； 4.管理性能测试团队。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (29, N'《暗区突围》手游-测试工程师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责暗区突围手游的测试工作，作为特性负责人带领子公司及外包同学一起保障产品质量； 2.负责制定对应特性组的测试计划、把控特性风险、推动测试流程&效率优化； 3.从黑盒和白盒的角度进行测试分析，制定测试方案，并跟进外包测试执行，持续优化测试方案； 4.针对游戏业务测试中的难点和盲区主动提出新的解决方案，开发对应的测试工具； 5.推进研发流程中质量问题和风险的解决，提升研发效能。
