INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (31, N'边缘基础设施运维工程师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.物理基础设施纳管； 2.负责边缘机房 GPU 服务器（NVIDIA A100/H100/L40S 等）、CPU 服务器、存储节点等物理设备的全生命周期管理，包括上架验收、固件/驱动升级、故障诊断与硬件替换； 3.建立和维护硬件资产台账与自动化纳管流程，保障设备信息准确、可追溯。制定并执行硬件巡检计划，定期输出设备健康度报告，对硬件 EOL/EOS 风险进行预警和替换规划； 4.边缘网络与机房运维； 5.负责边缘机房网络设备（交换机、路由器、防火墙等）的标准化配置、日常监控和故障处理，确保边缘节点到中心管控面的网络连通性与低延迟； 6.维护机房网络拓扑文档，参与带宽规划、链路冗余设计和网络割接； 7.与 IDC/运营商对接，处理机房环境（电力、制冷、机架空间）相关事宜，保障基础设施 SLA； 8.容器化平台与云原生运维； 9.管理和维护基于 Kubernetes 的边缘容器平台，负责集群部署、版本升级、节点扩缩容和资源调度策略优化； 10.实现 GPU 资源的容器化纳管：包括 GPU 驱动兼容性管理、GPU Operator 部署、MIG（多实例 GPU）配置、GPU 共享与隔离策略； 11.建设面向外部客户的算力交付流水线：容器镜像管理、Helm Chart 标准化、命名空间/租户隔离、配额管理、监控告警接入； 12.维护平台核心组件（包括但不限于 GPU Operator、P
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (32, N'腾讯云-可观测与运维平台高级研发工程师（深圳/杭州/北京/上海）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.AI原生产品演进：负责可观测与运维平台的架构研发。探索大模型与多Agent落地，推动平台向智能化、意图驱动（Intent-Driven）及自然语言交互（LUI）的新一代产品形态演进； 2.数据基础设施研发：负责高并发指标、日志、链路（Metrics, Log, Trace） 海量数据流水线的泛在采集、高性能多维存储与计算组件研发，持续优化系统性能与稳定性； 3.智能运维能力构建：利用AI重构并升级海量告警智能降噪、自适应动态拓扑、智能根因定位（RCA）及ChatOps交互式运维等核心产品能力，实现端到端智能闭环。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (33, N'Agent Infra SRE工程师(Agent治理方向)(深圳/北京)深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责 AgentRuntime 全地域（国内 + 海外）的服务可用性保障，承担日常值班、告警响应、故障定位与复盘，推动故障根因治理与长期改善； 2.建设和完善可观测体系：基于 OpenTelemetry / Prometheus / CLS / 智研平台，覆盖沙箱创建、调度、网络、存储等全链路的 Metrics、Tracing、Logging，驱动 SLO/SLI 指标落地； 3.参与容量管理与资源运营：监控多地域沙箱资源池（CPU/内存/存储）水位，推动弹性扩缩容策略优化，降低资源浪费，保障高峰期服务质量； 4.主导变更管控与发布稳定性：建立灰度发布、回滚、预案机制，结合 CI/CD 流水线推进发布过程风险管控； 5.参与平台可靠性设计：针对 CDB 慢查询、沙箱启动延迟、网络隔离策略等关键瓶颈，联合研发推进架构优化和稳定性加固； 6.负责 SRE 工具链与效能建设：开发故障自愈脚本、巡检工具、容量预测模型，沉淀 SRE 知识库，持续降低人工运维成本。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (34, N'大模型存储SRE工程师深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责存储类产品的日常运维，如需求评估、发布变更、容量管理等日常运维工作，以及7×24小时服务稳定性保障； 2.深度理解分布式存储产品架构与核心模块，参与产品需求技术评审和BCP治理，系统性挖掘现网风险隐患与性能瓶颈，制定完备的应急预案并组织定期演练； 3.主导存储产品运维体系的持续演进，构建自动化运营工具与平台能力，基于SRE理念推进故障管理、变更管理、容量管理等核心工程实践与演进； 4.探索AIOps方向的工程实践，包括基于机器学习的异常检测与告警降噪、容量趋势预测及资源管理，以及利用大模型辅助故障问题分析与运维知识沉淀； 5.保持对运维及AI领域技术探索，推进自动化与智能化工具在运维场景的合理应用，提升平台稳定性与运维效率。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (35, N'机器学习平台SRE工程师（深圳/北京）深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责机器学习平台的整体 SLA/SLO 定义、监控告警体系建设与故障应急响应，持续提升系统可用性，保障平台各个链路的稳定通畅； 2.负责机器学习平台的架构治理，容灾设计，性能调优。对接AI训练链路、资源调度与存储能力，参与业务和系统的问题排查工作； 3.负责运维运营工作自动化，借助AI能力来解决日常工作问题，包括资源管理、变更管理、故障恢复、用户工具诊断接口/mcp等。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (36, N'AI Infra SRE 工程师(Agent沙箱)深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.数据面：负责宿主机集群运维：内核、虚拟化栈、轻量虚拟机、容器运行时、版本管理与变更管控、大规模故障处理、机型适配；参与定位宿主机与实例侧疑难问题：虚拟化异常、内核 panic、性能抖动、IO 与网络异常； 2.控制面：负责平台 SLA/SLO 达成：定义并运营可用性、创建成功率、冷启动时延等核心指标，保障调度与控制面组件的可用性、容量规划与性能优化； 3.负责事件/变更/问题管理全流程：故障响应与升级、影响面评估与对外通报、复盘闭环与改进项跟踪； 4.建设全链路可观测体系（指标、日志、拨测、事件），推进运维自动化，沉淀原子工具与标准化 SOP，实现巡检、变更、故障处置等场景的平台化； 5.探索并落地 LLM、AI Agent 技术，结合运维知识库、监控数据与工具调用，建设智能告警分析、故障诊断与自动化处置能力； 6.负责容量与成本优化，联动研发团队推动故障复盘与容灾风险治理，以数据驱动稳定性改进。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (37, N'大数据 WeData 平台 SRE 工程师（深圳）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责 WeData 平台及大数据服务的稳定性保障、监控告警和故障处理； 2.优化任务调度、数据同步及计算存储性能，保障数据产出时效； 3.推进容量规划、资源利用率优化和成本治理； 4.建设自动化运维能力，完善发布变更、容灾及故障复盘机制。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (38, N'资深服务器运营工程师(规模化交付/AI提效)深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责服务器整机硬件的规模化批量交付，搭建标准化交付流程，设计系统级交付解决方案； 2.负责批量装机、镜像分发与交付测试脚本的开发和优化，用自动化工具替代人工操作，提升交付效率与质量； 3.负责服务器硬件故障诊断与定位，使用 BMC/SEL 日志、诊断工具与自写脚本完成硬件问题排查、调优与闭环； 4.负责将 AI 能力落地到交付与运维场景，用智能化手段优化交付流程的效率与质量； 5.负责交付过程中的问题跟踪与闭环管理，协同研发团队持续改进交付体验； 6.编写和维护服务器交付技术文档与标准作业流程，赋能团队与外部合作方。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (39, N'TIONE-大模型训推平台技术支持专家深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责腾讯云大模型训推平台客户2线技术支持，解决客户在训练、推理等环节遇到的技术问题，保障客户业高效、稳定运行； 2.定期复盘线上故障与客户问题，深入分析根因，优化技术支持流程与诊断工具，输出改进建议并驱动产品迭代升级； 3.深入分析平台可用性风险、瓶颈与容量热点，通过数据驱动方式识别风险与性能短板，持续推动架构优化与平台演进； 4.参与运维管理体系建设，负责可观测诊断平台、自动化运维工具的规划与开发，以及GPU资源、分布式训练、推理服务等组件的容量规划与性能调优； 5.探索AI Native、AIOps、Agentic 运维诊断等前沿方向，推动运维体系向智能化、自愈化与自治化演进。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (40, N'风控算法工程师深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.识别和挖掘腾讯流量的爬虫、自动机等机器流量风险，制定安全风控策略与解决方案，保证腾讯流量安全； 2.完善流量安全风控体系的建设，包括但不限于RAG等知识库的构建、基于大模型和Agent的应用、风控策略的自动化挖掘和效能工具的建设等。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (41, N'QQ-高级算法工程师深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.AI Agent 算法研究方向：探索工具调用、模型规划、长记忆、意图识别等核心能力；研究多 Agent 协同机制，推动 Agent 在实际业务中的落地； 2.多模态大模型研究与优化方向：主导多模态/全模态大语言模型的预训练、对齐与推理优化；推动图像、视频、文本等多模态理解与生成能力的持续演进； 3.多模态内容理解与治理方向：构建面向复杂场景的多模态内容理解能力；建设生态内容治理算法体系，支撑业务侧的理解、分析与交互需求； 4.图像/视频编辑与生成落地方向：研究并落地图像编辑、视频生成与编辑等 AIGC 能力。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (42, N'WorkBuddy-Agent Harness 算法工程师深圳', 1, N'学历不限', N'校招', N'IRE   ', N'1.负责 WorkBuddy Harness 的整体效果与能力优化，协同内部团队，以用户真实任务表现为反馈，不断优化迭代 Harness 效果；岗位为研究和工程复合型，可以偏向其中一个方向，但需要对另一个方向有所了解，更倾向于两者兼顾； 2.独立解决问题，提出原创性想法，从 0 到 1 驱动研究探索；同时拥有扎实的工程落地能力，打通从想法提出到落地实现的完整链路； 3.可针对全新问题定义合理的评测与验证标准，搭建配套评测数据集；立足真实业务场景，保证智能体能力在现实环境下有效可用； 4.包括但不限于以下研究方向：1）Harness Self?Evolution 方向：研究 Harness 闭环自进化机制，自主迭代工具集、执行架构与多智能体协作范式，适配模型能力与业务场景演进；2）Context Engineering 方向：探索复杂场景下的上下文组织与编排，在模型窗口和 token efficiency 约束下引导模型聚焦关键信息，提升 Agent 任务表现；3）Multi?Agent Coordination 方向：研究大规模分布式智能体协作，构建 Agent 集群化协作能力；4）Long?term Memory 方向：研究 Agent 长期记忆、经验内化与自我迭代机制，形成稳定的行为模式与长期决策准则；5）Long?Horizon 方向：研究长链路、稀疏反馈任务下的持续决策机制
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (43, N'游戏音频算法专家深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责游戏内音频算法的实现与优化； 2.系统化的设计与研发游戏业内领先的音频算法与音效解决方案； 3.解决游戏音频疑难问题。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (44, N'时光算法-高级工程师北京', 1, N'学历不限', N'社招', N'IRE   ', N'1.面向院前急救、灾害预警、银发科技等场景，负责算法方案设计与落地，持续提升业务效果。 2.负责领域 LLM、多模态模型及智能体的应用优化，包括模型适配、后训练、记忆与工具调用等。 3.建设评测基准与评测数据自动化生成、扩增能力，推动自动化评测、缺陷归因及算法迭代。 4.与产品、领域专家及工程团队协作，推动算法上线，持续优化效果、稳定性、时延与成本。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (45, N'腾讯地图-AI算法专家深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责地图出行领域大语言模型（LLM）的设计、训练、调优与评估，结合地图出行场景需求进行模型优化创新； 2.架构设计合理的AI架构，解决地图出行场景中的业务和技术挑战； 3.持续跟踪并分析AI大模型领域业界进展，探索技术突破方向，指导团队技术发展路径。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (46, N'腾讯地图-AI算法专家北京', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责地图出行领域大语言模型（LLM）的设计、训练、调优与评估，结合地图出行场景需求进行模型优化创新； 2.架构设计合理的AI架构，解决地图出行场景中的业务和技术挑战； 3.持续跟踪并分析AI大模型领域业界进展，探索技术突破方向，指导团队技术发展路径。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (47, N'微信搜索-Agent算法专家北京', 1, N'学历不限', N'社招', N'IRE   ', N'1.参与微信搜索Agent能力优化，包括Search Agent（DeepSearch/DeepResearch）和真实世界复杂任务上的Agentic能力； 2.跟进前沿技术：Mid-Train、SFT、GRM、PRM、RLVR、Agentic RL、Agent自进化、Context管理/Memory等； 3.探索稳定高效的Agentic RL方案，探索下一代大模型结合Agent结合搜索的技术和产品范式。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (48, N'QQ-#高级推荐算法工程师#深圳', 1, N'学历不限', N'校招', N'IRE   ', N'1.负责空间公域推荐链路优化，针对业务特点进行算法优化，提升用户体验及消费数据； 2.深入理解产品业务，洞察用户需求；工作内容包括不限于技术规划、case分析、数据挖掘、特征工程、模型开发、召回策略、排序策略； 3.能够紧跟工业界、学术界的前沿技术，结合大模型技术，升级推荐模型，LLM4Rec、生成式召回等，提升推荐效果。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (49, N'QQ-#社交推荐算法工程师#深圳', 1, N'学历不限', N'校招', N'IRE   ', N'1.优化QQ社交关系链相关业务推荐算法，提升用户体验及新增关系链等业务指标； 2.深入理解产品业务，洞察用户需求，工作内容包括不限于需求沟通、case分析、数据挖掘、特征工程、模型改进、策略开发； 3.能够紧跟工业界、学术界的前沿技术，基于QQ大规模社交图数据，结合大模型技术，升级算法模型，提升推荐效果。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (50, N'ima-数据分析师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责腾讯ima产品的核心业务数据的分析与监控，搭建并维护关键数据指标体系； 2.深入理解业务逻辑，通过数据分析挖掘潜在问题，提出优化建议； 3.支持团队的数据分析需求，负责业务的经营分析，协助团队看清业务经营现状。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (51, N'《金铲铲之战》-数据分析深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.支持游戏策划与运营的数据分析工作，围绕用户回流流失、活动效果、商业化表现、玩法参与和系统调优等进行监测和专题分析，识别问题并提出优化建议； 2.参与数据分析体系建设，包括指标口径梳理、数据看板搭建及日常数据提取，推动团队形成高效、稳定的数据使用机制； 3.开展用户研究工作，通过问卷、访谈、玩家反馈及行为数据等方式，理解不同用户群体的需求、体验和流失原因，并将研究结论转化为可执行建议； 4.支持游戏品类及市场研究，分析竞品玩法、版本趋势、用户生态和市场动态，为产品规划与运营策略提供参考。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (52, N'证券-用户数据分析师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.深入理解产品目标、用户需求与商业逻辑，与产品、算法及研发团队共同识别关键问题，将业务判断转化为可验证的假设，推动产品决策与迭代； 2.构建覆盖用户体验、活跃、留存及转化的指标体系，结合用户分层、行为路径与生命周期分析，定位增长机会，解释变化背后的原因，提出可执行的优化建议； 3.主导 A/B 实验设计与分析，规范指标选择、样本量估算、随机分流及效果评估，识别实验偏差，严谨判断收益、代价与适用范围； 4.探索 AI 产品的效果评估方法，关联内容质量、用户反馈与长期行为，推动形成“发现问题—提出假设—实验验证—迭代复盘”的持续优化机制。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (53, N'微信基础-数据分析师广州', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责微信基础功能相关的数据分析与数据科学工作，通过数据洞察、AB 实验、因果推断等方法支持产品优化和业务决策； 2.建立和完善指标、分析及归因体系，挖掘业务机会，评估产品功能和策略迭代效果，并推动分析结论落地； 3.与产品、运营、算法、研发等团队协作，独立完成从问题定义、方案设计、数据分析到效果跟踪的完整链路； 4.结合业务分析场景，主动探索 AI 工具在数据处理、分析和报告产出等环节的应用，提升分析效率和决策质量。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (54, N'企业微信-数据分析师广州', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责企业微信产品核心业务数据的分析与监控，搭建并维护关键数据指标体系； 2.通过对复杂多维数据的深度挖掘，建立业务增长的归因模型，为产品演进提供具备数理支撑的科学建议； 3.利用机器学习模型（如流失预警、用户画像分群、LTV 预测）提升 B 端客户的留存与生命周期价值。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (55, N'腾讯云成本数据分析经理深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责云计算成本的预算/核算体系建设与优化，推进并完善腾讯云供应链成本管理方案优化与落地，包括基础设施、产品、行业客户的成本测核算方案落地； 2.负责成本分析与管理，跨部门沟通协调推动，支持成本方案落地与经营分析辅助决策； 3.负责成本运营数据相关报表与系统的完善，监控及异动分析， 推动业务增长与成本优化。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (56, N'灰境行者-游戏数据分析师上海', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责构建和完善游戏项目运营数据分析体系，系统性整理、统计和分析日常游戏业务数据，撰写高质量的分析报告； 2.针对游戏项目开展专项数据分析，涵盖用户价值、流失分析、游戏生态、版本活动效果评估、用户画像分析等，为运营决策和产品优化提供数据支撑； 3.深入研究用户精细化运营策略，包括但不限于用户分层、精准营销和用户生命周期管理，推动用户价值提升； 4.主导游戏业务数据能力建设，包括底层日志结构设计、数据清洗流程优化、可视化报表平台搭建与维护； 5.沉淀数据分析方法论与框架，协同数据技术及开发团队进行数据建模，持续优化和迭代精细化运营分析体系。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (57, N'腾讯会议-数据分析工程师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责腾讯会议数据分析，洞察业务机会，发现业务问题，为产品迭代提供决策依据； 2.负责用户增长和商业化相关数据科学工作，通过ab实验和因果推断等方法，构建科学严谨的评估和分析体系，对业务收益进行评估，并提出优化建议，推动策略优化带来业务增长； 3.负责腾讯会议的指标体系搭建，包括数据链路建设，基础数据维护和数据报表构建； 4.持续产出行业洞察，跟踪分析行业趋势，洞察其中的机会； 5.探索统计、机器学习和因果推断等方法论，并推动相关方法在业务落地，产生业务影响力。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (58, N'腾讯云-官网高级数据分析师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责经营分析： 负责腾讯云官网经营分析，围绕流量、用户增长渠道、收入与成本等建设合理指标体系和目标管理机制，搭建并维护指标体系和经营看板，定期产出经营分析报告； 2.协助建设经营分析agent： 结合Agent能力，将数据监控和运营动作结合，提升经营效率； 3.协助营销团队达成指标： 拆解经营目标，持续追踪指标进度，发现风险和增长机会，并转化成可执行的策略建议，和营销、运营、产品团队一起推进落地，并跟踪效果，帮助业务达成指标。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (59, N'AI数据产品经理深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.规划和落地AI驱动的数据产品/工具，如AI 数据智能体、AI 自动化埋点、大模型评测等，协同算法、研发、产品、运营等团队，完成需求调研、方案设计、原型输出、项目推进、验收上线和持续迭代； 2.围绕大模型业务场景，搭建完善的量化评测体系，通过数据分析定位模型短板、数据缺陷，输出优化方案并推动落地； 3.深入理解 AI 研发、数据生产、数据治理、数据消费等业务流程，抽象共性需求，设计平台化、标准化、可复用的产品方案； 4.关注 AI 数据产品方向的发展趋势，结合业务需求持续优化平台能力和产品体验。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (60, N'大数据产品经理（深圳/北京）深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责数据 Agent 方向产品规划，面向数据开发、数据分析、数据治理、数据运维等场景，设计智能化产品能力； 2.梳理用户在找数、取数、写 SQL、建任务、查血缘、排障、指标理解等场景中的痛点，推动 Agent 化解决方案落地； 3.设计自然语言驱动的数据工作流，包括意图理解、任务拆解、工具调用、结果解释、异常处理和用户确认机制； 4.推动数据平台能力 Agent 化，将 SQL 查询、元数据、血缘、质量、调度、权限等能力封装为 Agent 可调用工具； 5.与算法、研发、数据平台和业务团队协作，推动产品从方案设计、原型验证到线上落地，并持续优化产品效果； 6.建立数据 Agent 的效果评估体系，关注任务完成率、准确率、采纳率、执行成功率和用户反馈闭环。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (61, N'证券-数据产品经理-BI分析方向深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.业务分析与效果评估：独立承接产品与运营的分析需求与研究课题，覆盖用户行为、转化漏斗、客群分层、运营策略与活动效果等；主导A/B实验设计与评估，用证据区分"有效、无效与证据不足"，客观衡量产品改动的真实增益，输出可落地的结论与建议； 2.前瞻专题研究：围绕业务中长期发展方向，主动识别值得研究的关键问题，前置开展用户洞察、市场与行业对标等专题研究，阶段性向产品与运营团队输入洞察与策略建议，让数据发现问题、让洞察牵引产品迭代； 3.指标分析体系与洞察落地：搭建并维护覆盖用户增长全链路的核心指标体系与分析看板，统一指标口径与数据标准；建立业务健康度监测与异动归因机制，沉淀可复用的分析模型与数据资产； 4.将分析结论转化为清晰的业务语言与策略建议，联动产品、运营、算法、研发与数据团队推动落地，持续跟踪效果、复盘迭代，形成分析、决策、验证的完整闭环。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (62, N'休闲游戏增长-高级数据产品经理深圳', 1, N'学历不限', N'校招', N'ECI   ', N'1.负责融合 AI + AB 实验能力到不同游戏细分品类的数据决策和业务增长中，包括产品工作的规划、落地、复盘，打造数据驱动休闲游戏增长之路，对接腾讯国内、海外休闲游戏； 2.负责增长相关工具平台建设，包括不限于 AB 实验、因果推断、AI 数据分析，配置发布系统等。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (63, N'微信小店-产品策划-数据产品方向广州', 1, N'学历不限', N'社招', N'ECI   ', N'1.理解用户在数据查找、口径确认、SQL编写等数据处理流程中的相关痛点，规划并推动相关的AI功能落地，包括但不限于Agent化的解决方案； 2.支持内部业务的经营分析、数据洞察、工程建设等事项，从中抽象相关的通用流程与基建，以此推动数据资产、数据分析等相关AI功能的产品迭代； 3.与算法、研发、数据等相关团队合作，推动产品从方案设计、原型验证到线上落地，并持续优化产品效果。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (64, N'腾讯游戏-AI agent开发-数据产品方向深圳', 1, N'学历不限', N'校招', N'IRE   ', N'1.参与开发部门内数据产品，推进数据分析、数据管理与数据应用平台的功能迭代与工程落地； 2.负责业务场景下数据产品的开发与优化，包括但不限于数据采集、数据处理、数据分析、数据可视化及数据应用等产品的数据能力建设与工作流整合； 3.持续调研数据产品、数据分析及 AI+Data 等领域的前沿技术，探索数据智能、自动化分析、指标体系、数据资产管理等方向的应用，并评估可行性推动落地； 4.与用研及业务团队协作，理解业务需求和数据使用场景，负责数据产品的方案设计与技术实现，将数据能力深度融入业务工作流，提升数据获取、分析与决策效率。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (65, N'金融科技-AI数据产品经理-数据开发方向深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.：面向金融风控和合规履职，深入理解业务场景，提炼数据逻辑和口径，与相关方配合完成数据项目交付，同时探索利用大模型和AI技术提升数据交付效率（如智能需求解读、代码生成辅助、自动化报表生成等）； 2.：参与部门大数据体系设计，包括数据标准与规范制定、数据资产管理、开发运营工具建设、数据治理推进等，推动AI能力与数据平台的深度融合，提升数据开发效率和交付质量； 3.：规划和落地AI驱动的数据产品/工具，如智能风控数据洞察、合规知识问答、异常交易模式识别辅助等，与业务、策略模型、合规、研发等多个团队合作将大模型能力转化为业务可用的产品功能。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (66, N'腾讯混元-混元多模态数据产品（北京/上海）上海', 1, N'学历不限', N'社招', N'ECI   ', N'1.岗位职责； 2.数据规划：负责图像/视频模型预训练、后训练的数据建设，与算法团队协同制定数据标准、生产方案及交付计划； 3.数据寻源：拓展公开数据集、授权内容、定向采集及合成数据等来源，综合评估质量、规模、成本与合规性； 4.质量筛选：建立清晰度、美学质量、图文一致性、视频时序与运动质量等评价标准，推动数据清洗、去重、描述生成及标注验收； 5.效果迭代：结合训练评估与问题归因优化数据策略，协同研发推动数据生产、质量监控与版本管理的平台化。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (67, N'腾讯云-大数据产品客户成功经理-for 海外深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责大数据产品国内及海外大项目交付管理，按合同约定完成产品交付，对产品交付的范围、进度、质量负责； 2.负责交付后客户维护和深耕，客户全生命周期管理，能够根据客户业务特点和需求，引导客户使用产品并进行深层价值落地，对客户大数据产品系统的健康度、使用深度负责，周期性拜访客户，维护客户关系； 3.据客户业务需求撰写方案，提供产品培训，解决用户关于产品的各种使用问题，持续挖掘客户业务场景，并为客户提供最佳使用实践； 4.甄别客户需求，对客户需求和反馈进行收集分析，提供产品优化建议，推动产品选代优化； 5.该岗位可 base 北京/深圳。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (68, N'AI Infra高级研发工程师深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责面向模型训练/研究场景下的中台基础设施建设，如沙盒平台、数据分析平台、Oncall平台、统一代理等公共服务的开发； 2.解决各基础设施平台的性能、稳定性问题，持续优化业务流程、保障模型训练链路的准确、高效执行； 3.与模型算法侧紧密协作，了解模型训练场景下的全链路流程与痛点，设计解决方案并最终落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (69, N'AI产品经理深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责企业 AI Agent 平台产品规划与建设，推动核心产品能力设计、研发协同及版本迭代； 2.负责 IMate 相关产品方向，包括基础能力建设、研发工作流集成、开放平台能力建设等； 3.结合企业内部研发和办公场景，洞察用户需求，探索 AI Agent 提升工作效率的新模式，并推动产品落地； 4.持续跟踪 AI 技术和行业发展趋势，推动产品能力、用户体验及应用规模持续提升。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (70, N'广告产品经理深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.产品规划与迭代：负责海外程序化广告搭建与SDK的功能设计和系统迭代，提升投播效率、广告效果与变现表现； 2.解决方案与能力覆盖：结合不同媒体赛道及区域市场特性，设计差异化的流量与预算策略；结合市场动态与业务需要，持续优化广告SDK功能设计，推动能力的规模化覆盖； 3.数据驱动优化：基于SDK埋点数据、投放效果与变现效率指标等，定位问题并制定优化策略。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (71, N'金融产品经理深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.领域研究与规划：基于区块链、稳定币等新领域，在海外市场完成竞品与用户研究。推演产品路线图和版本节奏；输出 PRD，写清功能、体验、安全和性能指标； 2.链上体验设计：把地址、Gas、签名、跨链等概念收进产品底层。基于账户抽象（例如EIP-7702）设计免 Gas、批量交易、密钥托管与恢复等方案，降低用户使用门槛； 3.资金与支付链路：设计法币与稳定币之间的流转和兑换逻辑，负责付款、收款、换汇等核心链路，并对接资金账户、支付通道等外部合作方； 4.架构与安全协同：和技术团队一起定义客户端、服务端、合作方系统之间的调用边界和权限模型，参与链基础设施的选型评估； 5.合规落地：和法务合规团队一起，把牌照要求、KYC/AML、Travel Rule 等监管规则转化为产品流程； 6.上线与增长：制定上线策略，联合运营和市场团队推动用户获取和留存，依据数据持续迭代。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (72, N'零信任产品经理深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.产品战略与规划?，主导零信任架构（含SASE、IAM、终端安全）的长期产品路线图制定，结合集团资源及SaaS化需求设计可扩展的安全解决方案； 2.深度分析全球零信任技术趋势（如微隔离、动态授权、终端合规检测、终端威胁行为分析），结合腾讯云优势，制定差异化策略，主导产品合作生态； 3.全生命周期管理?，负责终端安全软件/网关产品的迭代闭环，包括需求分析、原型设计（Axure/XMind）、版本交付及上线后运营优化； 4.建立产品核心指标监控体系（如客户流失率、ARR/MRR），通过数据驱动产品体验提升。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (73, N'服务Agent产品经理深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责服务Agent产品规划与体验定义，包含Agent架构设计、定义意图识别、任务编排、结果反馈的交互体验，设计出行生活方向的复合场景能力； 2.推动业务Agent落地，协调出行方向多交易业务Agent的需求与迭代，打通出行服务的完整交易闭环，并对接和业务侧资源； 3.负责Agent对外输出的基建能力建设，包括外输场景的标准产品架构、账号互通、订单及支付等解决方案设计； 4.定义AI原生体验方法论，围绕出行生活的场景，以提高交易确定性设计AI场景，沉淀可复用的AI产品体验标准； 5.数据驱动与闭环，搭建Agent效果评估体系，通过调用成功率、任务完成率、履约转化等指标持续优化，驱动工作流与工具能力迭代； 6.持续跟踪大模型与Agent领域的前沿进展，结合出行服务业务目标探索新场景，沉淀可复用的Agent平台能力。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (74, N'WorkBuddy- 移动端产品经理深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责WorkBuddy移动端整体产品规划与战略制定，统筹iOS/Android App、微信小程序、智能硬件终端等多端形态，明确AI办公功能在不同场景下的迭代方向和落地路径； 2.主导移动端产品的交互设计、信息架构及导航逻辑优化，结合移动端用户行为习惯提升AI功能易用性，确保跨终端体验一致性，同时对智能硬件联动场景提出创新产品设计思路； 3.持续跟踪国内外AI办公工具、移动智能助手及企业协同类产品的市场动态，深入分析金融、政务、法务等垂直行业的移动办公痛点，输出可落地的解决方案； 4.全程把控产品从需求调研到上线运营的全生命周期，独立编写高质量PRD文档，精准定义AI功能的交互逻辑、边界条件、异常处理机制及多端适配策略； 5.推动腾讯云生态与WorkBuddy移动端的深度融合，包括CloudBase部署、微信小程序兼容、企业微信场景打通及移动端API对接，设计高可用且可扩展的技术实施方案； 6.构建全面的产品指标体系（如任务完成率、AI响应有效率、功能渗透率、多端留存等），基于完整的数据埋点分析方法论，通过漏斗分析、路径对比等定位体验断点并提出优化策略； 7.关注AI办公领域前沿技术趋势（如多Agent协作、智能工作流编排等），运用vibe coding思维快速验证产品创意，推动创新功能的落地与迭代。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (75, N'电商-oms产品经理-云mall武汉', 1, N'学历不限', N'社招', N'ECI   ', N'1.系统规划与产品设计：主导电商 OMS 核心中台系统（订单管理、库存管理、履约配送、售后管理等）的整体产品规划与落地建设，结合业务现状与增长目标，设计高效稳定的产品体系，推动系统能力持续升级； 2.业务需求挖掘与分析：深耕供应链履约核心场景，涵盖订单履约、发票管理、财务对账、售后管理、库存管理等领域，能独立开展业务调研与需求挖掘，精准拆解业务诉求，输出清晰可执行的产品解决方案，有效支撑业务增长； 3.全流程产品负责：对产品全生命周期负责，贯通需求分析、功能定义、原型设计、项目推进到上线迭代的完整链路，确保每个版本按质按期交付，产品价值真正落地、效果可衡量； 4.该岗位签约主体为云智。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (76, N'WorkBuddy-Agent Harness 策略产品经理深圳', 1, N'学历不限', N'校招', N'ECI   ', N'1.负责 WorkBuddy Harness 的智能体策略优化，围绕用户场景、上下文流转和任务执行，设计并持续完善 Agent 策略体系； 2.独立拆解复杂的智能体应用场景，提出原创性的产品与策略思路，打通从问题定义、策略设计、实验验证到效果复盘的完整链路； 3.面向不同任务链路，在效果、稳定性与 Token Efficiency 之间取得合理平衡，推动产品目标达成； 4.针对不同场景定义合理的效果评测与验证标准，搭建配套评测数据集，通过实验和数据持续验证策略效果； 5.持续收集和分析用户反馈及线上数据，识别真实有效的优化方向，协同模型、工程、研究等团队迭代 Harness 效果。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (77, N'信用卡-平台产品经理深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责微信信用卡还款平台在微信生态内的场景挖掘与产品合作； 2.深度洞察用户，理解微信生态，挖掘生态内的场景连接点； 3.推动产品创新，实现平台与生态的共赢。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (78, N'QQ游戏平台-产品策划-用户体验与活跃提升方向深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责QQ游戏中心双端整体用户体验打磨与活跃提升，需深度理解结合游戏行业特性，通过用户需求洞察、体验策略设计及数据驱动迭代，探索QQ优势的用户价值，打造高粘性、高价值的用户生态，推动平台用户活跃、留存及长期价值增长； 2.用户体验诊断与策略制定 ：主导平台全链路用户链路分析，挖掘核心体验痛点，输出体验优化策略，推动体验从“可用”到“好用”的升级； 3.用户增长场景设计与落地 ：基于用户分层，设计差异化活跃策略，联动游戏/内容/社区资源，提升用户日均使用时长与核心功能渗透率； 4.跨端体验统一与创新 ：统筹PC、移动端等多端体验一致性，结合游戏用户“碎片化+沉浸式”需求，优化跨端功能适配。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (79, N'企业微信-AI产品经理-微信互通方向广州', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责企微&微信互通模块的产品策划工作，探索互通能力和 AI 的结合，如基于服务过程，洞察企业经营现状，输出问题诊断与优化建议； 2.深入理解不同规模、行业企业的对客服务场景，识别核心需求，抽象通用产品能力。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (80, N'开放世界-UE特效设计师(上海)杭州', 1, N'学历不限', N'社招', N'IAE   ', N'1.负责游戏项目中的特效制作，包括但不限于角色技能、环境动态以及场景中的各类交互元素特效； 2.配合TA，使用Unreal Engine进行高质量特效材质、效果开发及调试优化； 3.负责跟进特效外包的品质审核及进度跟进； 4.对已有资源进行分析并改进，提升总体视觉品质和运行性能。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (81, N'《火影忍者》手游-客户端开发-系统开发方向深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责游戏日常系统运营等模块的开发与维护； 2.负责相关工具链的开发与维护； 3.负责分析、定位、解决项目的疑难问题，以及对体验和性能方面的调优。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (82, N'QQ 经典农场客户端开发工程师-新星引力计划深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责游戏日常系统运营等模块的开发与维护； 2.负责相关工具链的开发与维护； 3.负责分析、定位、解决项目的疑难问题，以及对体验和性能方面的调优。
