INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (84, N'微信小店-产品策划-售后体验方向广州', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责微信小店交易纠纷的 AI 处理能力落地，包括智能判责、自动举证、话术生成、工单分流等核心环节的规划与运营；并持续打磨纠纷处理模型与策略的准确率和覆盖率，提升人效； 2.能够深入理解用户在电商交易的售后链路和体验痛点，针对不同问题场景与不同用户分层，设计差异化、可落地的处理策略； 3.以用户视角出发，对用户在纠纷的全链路体验做拆解与优化，提升用户在纠纷中的安全感、公平感与解决效率。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (85, N'在研3D动作游戏-资深UE5游戏客户端开发工程师（深圳/北京）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责Gameplay玩法系统开发与相关技术攻坚； 2.负责客户端玩法框架的设计、搭建与持续优化，提升游戏表现力和开发效率； 3.负责游戏玩法系统及工具链的研发，配合策划、美术等角色，高效实现游戏功能，并对技术方案进行可行性评估与设计； 4.负责优化游戏客户端性能和体验调优。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (86, N'魔方市场用户研究经理（动作线）深圳', 1, N'学历不限', N'社招', N'IAE   ', N'1.跟进工作室重点产品全生命周期研发运营过程，深度分析产品问题，建立评估体系，帮助提升游戏质量和用户体验； 2.应用游戏行业长期积累经验，独立挖掘并主导长期课题，灵活应用用户调研、产品拆解、数据等信息形成综合判断，落地支持业务方； 3.前瞻性的研究课题，包括但不限于特定市场/特定人群/特定业务问题的专项研究课题。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (87, N'魔方市场用户研究经理（射击线）深圳', 1, N'学历不限', N'社招', N'IAE   ', N'1.负责跟进工作室重点产品全生命周期研发运营过程，深度分析产品问题，建立评估体系，帮助提升游戏质量和用户体验； 2.应用游戏行业长期积累经验，独立挖掘并主导长期课题，灵活应用用户调研、产品拆解、数据等信息形成综合判断，落地支持业务方。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (88, N'市场与用户研究经理-数据分析方向深圳', 1, N'学历不限', N'校招', N'IEC   ', N'1.能够独立完成游戏行业基础数据调研、常规人群调研等任务，对国内和海外行业趋势和大盘发展有一定认知，能够围绕市场规模、产品表现、用户行为、竞品动态等，清洗、整合内部数据、三方数据、公开渠道数据等多源信息，构建可复用的行业数据资产； 2.运用统计分析、可视化等方法对多来源数据进行深度加工与交叉验证，识别关键趋势、异常与规律，确保结论客观、口径清晰、可追溯； 3.结合对游戏行业的理解，从数据中提炼有商业价值的洞察与判断，独立撰写高质量数据分析报告，为业务决策提供前瞻性和落地性输入； 4.善用AI工具重构数据搜集、处理与报告产出流程，持续沉淀分析模型、指标体系与自动化工具，提升团队研究效率并形成方法论积累。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (89, N'天美游戏-游戏产品战略经理深圳', 1, N'学历不限', N'社招', N'ECS   ', N'1.深度追踪全球游戏市场前沿动态，进行前瞻性扫描；推动天美工作室群制定契合市场发展方向的中长期产品战略； 2.进行专家级游戏评测，结构化拆解竞品的核心玩法、系统框架、心流体验及核心用户心理，为天美在新赛道的布局提供敏锐的品类风向预测； 3.深度参与天美工作室群的项目研发和运营支持工作，从市场分析、战略推演、产品分析、用户研究等不同角度对内部工作室和重点项目提供战略支撑； 4.沉淀系统性的游戏拆解与市场分析方法论，将碎片化信息沉淀为高价值的知识网络；定期向工作室群管理层及各核心项目输出高质量的战略洞察； 5.与平台智能团队协作，持续发掘前沿游戏行业机会和AI 领域的趋势研究。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (90, N'《火影忍者》手游- 营销推广深圳', 1, N'学历不限', N'社招', N'ECS   ', N'1.根据产品不同阶段的需求，负责推广策略的制定和推广方案的执行落地； 2.以增长为目的，不局限于单模块工作，需充分利用事件营销、渠道合作、直播、内容、BD、公关、媒介等模块，为项目结果负责； 3.主动挖掘和拓展内容及渠道合作的可能性，有能力跳出框架并充分利用渠道能力实现用户增长； 4.主导产出优质有创意的内容及合作落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (91, N'《三角洲行动》高级交互设计师深圳', 1, N'学历不限', N'社招', N'IAE   ', N'1.研究产品玩法和系统在交互设计上的统一性和平衡性，结合产品世界观打造叙事化、情感化设计，基于玩家与内容洞察持续优化创新交互体验； 2.洞悉行业趋势，精通用户、品牌及产品运营，熟悉竞品设计推广，可结合案例拆解产品架构、设计理念与交互逻辑； 3.以”内容型“为驱动思考设计的创意包装，通过对设计目标的拆解，定位符合游戏叙事的交互形式； 4.对设计过程的信息进行有意识的总结提炼，通过成功案例的验证形成可复制的设计经验及模式； 5.结合市场、玩家、技术、IP 等维度研判行业现状，输出适配项目的最优设计策略，推动落地并打造专业竞争优势。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (92, N'《金铲铲之战》-发行运营推广深圳', 1, N'学历不限', N'社招', N'ECS   ', N'1.根据产品不同阶段的需求，负责运营推广方案的制定和执行落地； 2.以增长为目的，不局限于单模块工作，需充分利用事件营销、渠道合作、直播、内容、BD、公关、媒介等模块，为项目结果负责； 3.主动挖掘用户增长点，拓展内容及渠道合作的可能性，有能力跳出框架并充分利用渠道能力实现用户增长； 4.深入理解产品特性与卖点，能根据玩法、风格产出优质创意内容及推动合作落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (93, N'《英雄联盟》-用户洞察经理深圳', 1, N'学历不限', N'社招', N'IAE   ', N'1.统筹用户研究体系：规划并执行定性与定量用户研究项目，覆盖从概念验证、用户测试到上线后体验追踪的全生命周期； 2.深度数据分析：搭建并维护核心用户行为数据看板，挖掘数据背后的用户动机、痛点与行为模式，输出可落地的洞察报告； 3.市场与竞品洞察：具备全球视角，持续追踪中国戏市场趋势、竞品动态及玩家文化变迁，预判行业机会点； 4.赋能产品决策：联动策划、发行、运营团队，将洞察转化为具体的产品优化方案、发行策略及营销抓手，推动落地； 5.方法论沉淀：建立标准化的用户洞察流程与知识库，提升团队整体用研效率与质量。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (94, N'腾讯云国际-海外运营经理深圳', 1, N'学历不限', N'社招', N'ECS   ', N'1.海外区域商业化lead-to-cash全过程管理与监控，对LTC漏斗的关键环节进行数据分析与指标管控，牵引经营结果； 2.从业务角度分析并梳理海外区域运营数据，定期输出与指导，复盘与提炼改进措施； 3.跨团队协作拉通主导，通过协作规则与流程的优化等，建立高效协作模式与提高合作粘性； 4.负责海外区域重点项目落地推动支撑，加速收入转化，预测偏离度提升与主导管理； 5.根据部门管理要求和业务发展需要，提升整体经营管理的能力和效率。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (95, N'AW 项目组-AI 互动影游创作平台产品策划深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责 AI 互动影游创作平台及工具的产品设计，包括需求分析、功能定义、原型设计和体验闭环，解决互动影游创作者在剧本、分镜、节点、视频生成和交互预览中的核心痛点； 2.结合 LLM、Agent、多模态、AI 视频/图像生成等能力，设计 AI 生成体验的产品形态，将复杂技术能力转化为可理解、可控制、可复用的用户交互和创作流程； 3.与研发、交互、视觉、策划、算法等团队协作，推动核心产品模块从 0 到 1 落地，确保产品质量、稳定性、易用性和可扩展性； 4.跟踪 AI 互动影游、AI 原生游戏和创作工具的发展趋势，结合用户反馈和项目验证，持续优化产品策略、功能优先级和体验方案。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (96, N'人力资源平台部-AI应用开发工程师深圳', 1, N'学历不限', N'社招', N'SEC   ', N'1.负责HR领域大模型及AI Agent在业务场景中的应用落地，牵头重点AI项目的方案设计、推进交付、效果优化与持续迭代； 2.负责HR领域业务系统的AI原子能力建设，推动相关能力标准化、组件化沉淀，并支持不同业务场景复用； 3.跟进AI领域前沿技术，评估并引入适配的技术方案，推动其在实际项目中落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (97, N'人力资源平台部-HR运营与体验专家深圳', 1, N'学历不限', N'社招', N'SEC   ', N'1.设计并推动HR共享服务核心业务场景的运营与交付管理，建立效率、质量、体验、风险等多维运营体系，保障服务流程高效稳定运行； 2.推动AI、Agent等能力在共享服务场景中的落地应用，探索AI与人工协同的新型服务模式，助力服务从被动响应向主动服务转变； 3.基于服务数据、员工声音和业务反馈，识别运营问题并建立洞察与反馈机制，推动HR政策、流程和产品持续优化； 4.打造面向未来的服务运营团队，推动团队能力升级、工作模式创新，建设学习型、数据驱动型的HR共享服务组织。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (98, N'腾讯云 DataBuddy-机器学习平台高级工程师北京', 1, N'学历不限', N'社招', N'IRE   ', N'1.MLOps全链路建设：负责数据、特征、训练、版本、评测、部署、推理、监控迭代全流程工程化建设，标准化AI研发交付流程； 2.企业级特征平台落地：主导 Feast 架构落地与优化，搭建离线/在线统一特征体系，完成特征物化、回填、版本管理与高并发在线查询，治理特征漂移与一致性问题； 3.自动化训练流水线：基于 MLflow/Kubeflow/Airflow 搭建训练调度、实验追踪、版本管理自动化流水线，提升算法迭代效率； 4.模型服务化工程：基于 Docker/K8s 完成模型容器化部署、灰度发布与弹性扩缩容，优化在线推理、批量预测性能，保障高可用、低延迟、高吞吐； 5.AI可观测与稳定性：搭建数据、特征、模型指标、漂移、推理异常监控体系，形成告警与迭代闭环，保障线上模型长期稳定运行； 6、该岗位可 base 北京、深圳、杭州、上海。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (99, N'微信-后台开发高级工程师-机器学习工程方向广州', 1, N'学历不限', N'社招', N'IRE   ', N'1.研究AI模型推理加速技术在微信业务中的应用，参与TFCC服务平台和推理引擎的研发与优化，提升推荐模型、大模型、传统中小模型等业务场景的推理性能； 2.负责微信后台AI算法的工程应用与优化，支持语音识别、语音合成、视觉理解、大语言模型等业务的后台工程开发与优化； 3.跟进AI领域的最新动态，优化内部技术方案，提升平台性能，推进AI架构升级。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (100, N'企业微信-机器学习平台调度工程师-（成都/北京）广州', 1, N'学历不限', N'社招', N'IRE   ', N'1.主导大规模GPU集群的全局资源调度，通过精细化管理和优化策略，显著提升资源利用率，确保离线和在线任务的高效稳定运行； 2.深入优化RDMA高速网络、分布式存储与计算资源的协同调度，有效解决大规模训练任务中的性能瓶颈，提升整体计算效率； 3.基于Kubernetes、Docker等云原生技术，构建高可用调度框架，全面支持分布式训练框架，实现任务编排、容灾与混部能力，并深入K8s调度器、CSI插件及CRD的开发，推动大规模训推技术的实际落地； 4.积极探索混合云、虚拟化等异构计算等前沿方向，不断推动技术与平台能力的升级和创新。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (101, N'机器学习平台资源调度工程师（北京/深圳/上海/杭州）北京', 1, N'学历不限', N'社招', N'IRE   ', N'1.主导万卡级GPU集群的全局资源调度，通过精细化管理和优化策略，显著提升资源利用率，确保离线和在线任务的高效稳定运行； 2.深入优化RDMA高速网络、分布式存储与计算资源的协同调度，有效解决大规模训练任务中的性能瓶颈，提升整体计算效率； 3.基于Kubernetes、Docker等云原生技术，构建高可用调度框架，全面支持分布式训练框架，实现任务编排、容灾与混部能力，并深入K8s调度器、CSI插件及CRD的开发，推动大规模训推技术的实际落地； 4.积极探索混合云、虚拟化、ARM异构计算等前沿方向，不断推动技术与平台能力的升级和创新。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (102, N'微信小店-数据科学-治理方向广州', 1, N'学历不限', N'校招', N'IRE   ', N'1.负责微信电商治理的数据分析，问题洞察发现，保障微信电商体系下的用户安全购物体验及公平合规的商家达人经营环境； 2.搭建电商系统运营及治理指标体系，运用统计学知识，刻画治理策略对微信电商生态的影响； 3.利用 abtest、因果推断等方法驱动运营决策。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (103, N'企业微信-大模型算法工程师-企业经营分析（成都/北京）广州', 1, N'学历不限', N'社招', N'IRE   ', N'1、与数据、产品、工程等团队紧密配合，参与算法选型到模型优化的全流程，充分利用大模型从业务资料中挖掘潜在的经营模式和用户行为规律； 2、专注用户行为理解和模式识别，利用社区发现、图模型、行为序列、LLM等技术进行用户画像分析、需求预测、营销策略优化、企业经营提效； 3、跟进LLM以及agent相关前沿技术，推动技术框架持续迭代升级，保持行业同类竞品前沿水平；
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (104, N'微信小店-高级推荐算法工程师广州', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责微信小店的推荐技术研发，包括但不限于召回、精排、重排、冷启动等； 2.负责微信小店核心场景的策略优化，钻研推荐算法的改进和调优，服务亿级电商用户； 3.与产品、工程、运营团队深度合作，理解业务发展，参与制定推荐策略的目标。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (105, N'《三角洲行动》-数据分析（经济安全方向）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责产品经济安全（包括交易市场和对局环境模块）的分析体系搭建、检测模型设计，和相关工作的落地执行； 2.根据游戏环境变化，基于数据、舆情和产品理解持续完善策略模型，及建立游戏安全风险预警机制； 3.以数据和用户洞察为出发点，协同业务团队，完善安全产品功能，为玩家和产品安全体验负责。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (106, N'光子 AI-AI Infra工程师深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.模型训练和推理平台开发； 2.研究并应用模型优化技术到训练流程和在线服务中，提高运行时性能，降低资源占用； 3.业务侧模型部署和评测； 4.团队 gpu 资源管理与调度。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (107, N'光子 AI-AI应用开发工程师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责游戏场景下 AI 应用的后台研发，包括 AI Agent、AIGC 工具等业务模块； 2.参与 AI 服务通用能力建设，包括模型接入、任务编排、上下文管理与记忆机制、工具调用、数据处理等； 3.负责 AI 服务工程化与线上稳定性建设，包括部署发布、监控告警、限流降级、故障排查、性能与成本优化。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (108, N'AI产品经理-AI平台（Agent）方向深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责金融科技AI平台产品的规划、设计和迭代，覆盖 Agent 研发流程、观测、追踪、安全、调优及成本控制等方案； 2.负责金融科技AI工具平台，挖掘技术/非技术用户内部场景痛点，完善产品能力； 3.参与组织级研发体系升级，梳理并设计多角色 Agent协同产品解决方案； 4.建立 AI 服务效果评估治理，通过数据、用户反馈和 Badcase 持续优化产品。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (109, N'光子 AI-后台开发-UE DS & AI bot 方向深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责 AI Bot 系统的研发与落地，结合游戏玩法探索强化学习等 AI 技术在 Bot 行为决策中的应用，提升 Bot 智能表现、运行稳定性和多人对战体验； 2.负责 UE DS功能开发与性能优化，覆盖寻路、物理、AI感知、网络同步等模块，提升 DS 运行效率、稳定性与承载能力； 3.负责 AI 算法与 Agent 能力的接入、评测与优化, 推动 AI 在游戏研发与业务场景中的落地应用。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (110, N'企业微信-AI产品经理-效率办公 AI广州', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责企业微信文档、智能表格 AI 能力的策划与定义，包括需求调研、产品设计、效果评测及上线推动； 2.深入理解文档创作、表格处理、数据分析、业务协作中的真实需求，持续打磨产品体验； 3.探索 AI 在文档与智能表格中的应用，通过大模型与 Agent 提升内容生成与编辑、信息整理、数据分析、可视化等工作的效率； 4.与研发、算法、设计、运营等团队紧密协作，推动 AI 产品从方案设计到上线迭代； 5.基于用户反馈、真实场景中的使用效果，持续优化 AI 能力与产品效果。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (111, N'游戏AI-数据挖掘算法专家深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.负责大数据在游戏AI等相关领域的算法与产品化等工作，包括但不限于如下方向：用户增长、因果推断、匹配系统、归因分析、千人千面体验流、商业活动/道具个性化推荐等； 2.负责前沿技术跟进，能够识别技术的有效性并快速应用； 3.负责具体项目落地，运用大数据+AI为项目带来可观的收益。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (112, N'英雄联盟手游-应用研究-数据挖掘方向深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.运用统计建模、机器学习及数据挖掘技术，设计并优化游戏用户体验，为游戏设计与运营提供精准数据支撑； 2.深入参与游戏增长数据分析，通过数据挖掘、因果推断等手段解决成长分析、匹配优化、AI投放、恶意行为对抗等核心业务问题； 3.积极拥抱新技术，主导或参与工作室多个项目的AI效能工具、生成管线的智能提效工作。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (113, N'粒粒的小人国-游戏运营-数据分析上海', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责粒粒的小人国及其他筹备新品的手游数据分析工作，包括数据体系搭建、持续的版本表现分析、以及用户和市场数据研究等； 2.负责数据体系搭建，如数据打点、上报和经分系统的搭建等，建立关键指标的日常监控机制，搭建各类专项数据分析框架； 3.负责市场和用户数据分析，根据游戏定位，进行目标用户分层，预估市场规模和用户空间，并能根据目标用户属性反推游戏设计； 4.进行竞品监测，保持对核心竞品和新游的关注，监控关键数据表现，为游戏提供方向性指导和参考。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (114, N'光子 AI-游戏数据科学专家深圳', 1, N'学历不限', N'社招', N'IRE   ', N'1.利用游戏海量数据，设计和构建游戏大模型，包括但不限于社交网络分析，推荐，异常用户挖掘等，为产品设计研发及运营提供支持； 2.数据特征算法：负责海量文本&多模态数据（图像，视频，音频，3D）的内容理解（如分类标签体系、embedding表征、Caption生成等），质量检测（低质识别检测、优质美学评价等），去重/聚类分析，数据合成等算法； 3.关注行业前沿动态，保持行业敏感度，对竞品有专业的研究和分析。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (115, N'腾讯营销-数据Agent产品经理(深圳/上海)深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责营销业务数据智能体产品的规划和落地。围绕营销数据资产管理和应用全链路建设智能体产品； 2.构建智能体产品评测和迭代的闭环体系，与工程和算法团队协作，持续推动智能体产品质量持续提升； 3.封装和优化面向 Agent 的各类基础数据工具，总结沉淀各类业务知识、分析诊断 SKILLS； 4.结合AI和 Agent 技术的发展趋势，探索 AI 在数据赋能和工作提效中的新应用，扩展产品形态和能力边界。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (116, N'《QQ三国》游戏运营成都', 1, N'学历不限', N'社招', N'IEC   ', N'1.负责游戏短视频官号的内容运营，包括整体策略规划、资源管理、创作者 / 主播扶持政策制定及落地执行， 并推动游戏直播生态建设； 2.负责内外部渠道的宣发、联动策略制定及落地，结合游戏特点拓展合作品类，拉动游戏回流； 3.负责游戏重要节点的对外统筹和活动支持：包含文旅、地方机构联动，组织大型用户见面会等； 4.支持游戏的重点数据分析工作，围绕用户活跃、经济、回流流失、超核、用户画像等模块进行监测和专题分析，了解和分析掌握玩家动态，给出有效建议。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (117, N'反洗钱风险分析师(成都)成都', 1, N'学历不限', N'社招', N'IEC   ', N'1.通过数据分析识别洗钱风险，挖掘洗钱特征，发现新型洗钱手法； 2.分析业务场景风险，通过机器学习与数据挖掘等技术手段，识别支付领域各类违法犯罪风险； 3.搭建风险特征体系，提升风险识别效率。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (118, N'腾讯云-安全策略工程师-反入侵方向北京', 1, N'学历不限', N'社招', N'IEC   ', N'1.针对安全风险事件的发现、跟踪、分析和协调处理，安全事件应急响应，同时能对安全事件进行影响范围评定、利用复杂度分析等； 2.反入侵策略的建设与运营，通过大数据分析和挖掘发现腾讯云平台中出现的各种恶意行为，制定相应的安全策略检出威胁； 3.参与入侵检测、应急响应体系设计和实践落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (119, N'商业分析师/商业分析经理（金融科技方向）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.深入支付、信贷、理财、证券等金融科技业务场景，分析金融科技的运营数据、商业环境、业务问题，形成高质量汇报材料； 2.拥有优秀的沟通和项目推进能力，帮助业务一号位，协同各部门推关键事宜； 3.有优秀的工程能力，能利用大模型将核心会议资料搭建成业务管理agent。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (120, N'微信支付-商业分析经理深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.行业与竞争研究：持续跟踪支付、消费、电商、金融科技、AI等重点领域，监测行业数据和竞争对手动态，研究行业趋势、监管变化、商业模式及主要玩家策略，识别可能影响业务的机会与风险； 2.经营分析与问题诊断：深入洞察支付行业及消费等核心场景，围绕业务规模、用户、商户、交易、收入、成本和投入产出等指标搭建分析框架，定位增长瓶颈和经营问题，协助业务明确目标、关键路径及资源规划，并提出改善建议； 3.战场协同与项目推动：针对复杂业务问题独立完成问题拆解、假设提出、数据验证和方案设计；协同支付线各经营战场，推动产品、运营、数据、政策、财务等团队形成共识、协同作战，并对战略性攻坚方向和重点项目从方案制定、实施落地到效果复盘负责。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (121, N'腾讯游戏-AI方向资深商业分析师深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.关注AI大模型等领域的最新动态、前沿技术突破和应用趋势，能够快速响应并及时整理和输出有价值观点； 2.参与AI产品（AI图像/视频/3D/动画生成等）和游戏AI功能的深度测评，对技术架构、产品设计、用户体验等维度进行拆解，输出专业分析； 3.针对AI技术与游戏领域的结合与应用（包括AI生成技术对游戏开发提效、AI驱动的玩法创新、AI与游戏的融合趋势等）进行分析研究，产出有洞察、可落地的结论，为管理层的策略制定提供支持。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (122, N'天美游戏-资深商业分析经理（AI方向）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.创新战略研判：立足游戏视角，关注“AI+游戏”等前沿趋势，统筹研究新兴领域对研发管线、产品形态及行业格局的影响，为管理层提供决策支持； 2.业务支持：深入业务场景，探索AI等创新实践与业务的结合点； 3.研究体系构建：前瞻识别高价值研究方向，带领团队展开深度专题研究，构建并不断迭代研究体系，沉淀商业洞察； 4.团队建设赋能：负责团队搭建、管理与人才培养；推动创新提效工具的探索与规模应用。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (123, N'腾讯战略发展部-高级商业分析师-AI方向深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.分析AI领域的前沿技术、产品机会和探索商业模式； 2.对游戏、电商、视频、社交、效率工具等应用领域深入洞察，协助业务明确目标及规划相关资源，为业务团队提供发展建议； 3.监测市场行业数据、竞争对手动态，对重点公司/业务情况进行深入分析，寻找业务提升的潜在机会点； 4.作为PMO，横向协同业务各部门，为战略性攻坚方向、战略性项目的实施落地负责。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (124, N'腾讯战略发展部-高级商业分析师-游戏方向深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.深入理解游戏行业，洞察关键市场趋势与用户行为，识别潜在的机会和增长点； 2.通过数据分析、市场调研和竞品分析，为集团及业务部门提供战略决策支持，推动战略性项目的落地并确保目标达成； 3.积极探索AI原生游戏等交叉领域前沿趋势，识别并推动关键业务机会。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (125, N'腾讯战略发展部-商业分析经理-金融科技方向深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.行业趋势洞察：负责追踪宏观环境与行业动向，洞察支付、理财、证券、保险、信贷等行业的前沿趋势、市场格局、竞品动向、用户需求及技术变革。制定整体金融科技业务的战略规划，挖掘商业机会，应对冲击挑战； 2.业务策略优化：围绕腾讯在金融科技领域的业务布局，以数据驱动决策，推动目标管理与达成，引导和支持业务能力升级和转型； 3.跨团队协同推动：参与战略布局所需的跨团队专项项目，与产品、运营、科技、财务、法务团队紧密合作，推动落地。同时，联动腾讯生态公司的合作伙伴，对协同发展提供专业支持。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (126, N'天美游戏-商业分析经理（AI方向）-新星引力计划深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.前沿洞察： 立足游戏行业视角，持续追踪“AI+游戏”等前沿趋势，深度分析新兴领域对研发管线、产品形态及行业格局的影响，为管理层提供决策支持； 2.业务支持：深入业务场景，探索AI等创新实践与业务的结合点； 3.体系沉淀：聚焦重点关注领域，开展深度专题研究，形成体系化知识沉淀与方法论； 4.工具赋能：灵活运用AI Agent等创新工具，持续优化日常工作效率。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (127, N'混元模型商业化运营负责人/专家（深圳/北京）深圳', 1, N'学历不限', N'社招', N'IEC   ', N'1.Token 增长与全生命周期运营：负责大模型 API / Token 业务的整体商业化运营，端到端对有效 Token 消耗量增长、服务质量负责； 2.拆解并监控核心用量指标（Prompt Caching、Batch Processing、长上下文等Token），结合主流高频场景（Agent、代码生成、搜索增强等）推动落地； 3.商业分析、量化建模与经营预测：做好Token 成本（GPU 算力成本 + 传输 + 调度）、毛利贡献及 LTV/CAC等分析，提供商业可行性评估； 4.供需平衡与资源测算： 基于各时区流量与并发峰值，构建 Token 需求预测模型，联动算力团队推导容量规划与服务策略； 5.全景经营看板与归因： 建立海外 Token 商业化指标体系，定期产出经营分析报告，定位预算偏差与业务异动归因； 6.海外 GTM 策略与生态落地：协同运维、部署等团队。跟踪竞品商业策略，设计具备竞争力的出海定价体系； 7.协同腾讯云等兄弟团队，推进海外 ISV、垂直 SaaS 伙伴的联合推广，优化从“自服务调用”到“大客户专属资源交付”的转化链路。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (128, N'代号：Craft-交互设计师深圳', 1, N'学历不限', N'社招', N'IAE   ', N'1.ai agent游戏平台核心体验设计：负责craft整体交互架构与流程设计，通过系统化设计降低操作复杂度，提升易学性与易用性； 2.小游戏模板交互：负责craft中官方小游戏模板的交互设计。熟悉热门小游戏玩法与交互流程，能够快速产出规范统一、流程清晰的各类小游戏交互方案； 3.用户研究与数据驱动：深入理解创作者与普通玩家的行为模式与核心痛点，通过用户调研、数据分析等方法定位编辑器的使用瓶颈与流失点，持续驱动产品体验与创作效率的提升； 4.交互文档与原型输出：输出高质量的交互原型，编写清晰的交互说明文档，并协同UI、程序、策划团队，确保设计方案的高质量落地； 5.建立与维护设计系统：主导建立并持续维护设计组件库与规范，确保设计语言的一致性，提升团队协作与开发效率； 6.跨部门协作：紧密对接策划，将功能需求转化为合理的界面逻辑；协同技术美术与开发团队，评估实现可行性。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (129, N'《逆战：未来》交互设计师深圳', 1, N'学历不限', N'社招', N'IAE   ', N'1.根据现有版本内容框架，负责游戏的交互设计拓展及战斗玩法体验的持续优化； 2.与跨职能团队合作，从交互专业角度创新高效地提出游戏设计方案； 3.跟进UI界面设计的各阶段，从方案概念到视觉设计，从界面开发到最终的功能验证； 4.运用线框图、故事板、用户流程等工具，有效传达交互和设计思路； 5.持续对游戏内容进行用户研究，收集体验反馈并输出优化方案，以提升玩家体验； 6.完善交互规范细则，持续提升项目交互设计品质。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (130, N'《王者万象棋》交互设计师成都', 1, N'学历不限', N'社招', N'IAE   ', N'1.体验痛点挖掘与提案：不等待需求，通过深度试玩、数据分析和竞品解构，主动发现当前交互体系中的效率瓶颈或情感断层，输出具备商业价值和技术可行性的优化方案； 2.前瞻性体验定义：针对自走棋品类的未来进化（更强的社交互动、更深度的赛季变革、跨平台无缝衔接），进行前瞻性的交互概念设计，并以 Demo 或可视化方案向决策层进行演示汇报； 3.全程跟进设计实现过程，与策划、视觉，动效、程序密切协作，确保最终版本实现品质与设计相符。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (131, N'《使命召唤手游》交互设计师深圳', 1, N'学历不限', N'社招', N'IAE   ', N'1.参与游戏产品的用户体验流程设计，协助构建信息架构，界面交互设计，保障交互体验的流畅性； 2.参与IP设定进行界面与交互的概念包装设计，塑造沉浸式IP体验； 3.参与用户研究与测试，并能基于反馈对设计方案进行交互体验的优化迭代； 4.参与现有游戏产品的可用性走查与体验评估，并输出优化建议； 5.参与设计和维护团队设计规范，协助维护设计一致性，参与落地质量验证。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (132, N'UE微恐轻动作项目-交互设计师深圳', 1, N'学历不限', N'社招', N'IAE   ', N'1.作为交互体验方向的设计人员，定义核心玩法、局外系统、社交与商业化场景的体验框架、信息架构和设计标准； 2.主导复杂系统从用户路径、任务流、状态流、原型、动效说明到引擎落地的全流程，对最终可用性和品质负责； 3.统筹交互、视觉、策划、程序、技术UI、QA等协作，解决复杂系统在移动端操作、反馈、可读性和效率上的体验问题； 4.建立交互规范、组件库、验收标准和体验走查机制，推动高频界面与核心流程持续迭代； 5.结合测试观察、用户反馈、竞品拆解和数据指标，形成可复用的体验优化方法并带动团队能力提升。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (133, N'《怪物猎人：旅人》-交互体验设计师（UX）深圳', 1, N'学历不限', N'社招', N'IAE   ', N'1.负责《怪物猎人：旅人》系统与战斗的双端交互体验设计与流程优化； 2.建立并维护跨端交互设计规范，确保双端操作逻辑、信息架构与反馈节奏上的交互适配性； 3.与跨职能团队合作，从交互专业角度创新高效地提出游戏设计方案； 4.跟进UI界面设计的各阶段，从方案概念到视觉设计，从界面开发到最终的功能验证； 5.持续对游戏内容进行用户研究，收集体验反馈并输出优化方案，以提升玩家体验。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (134, N'企业微信-AI产品体验设计师广州', 1, N'学历不限', N'社招', N'IAE   ', N'1.负责企业微信移动端/桌面端/web端等设计工作； 2.参与产品初期的构思讨论，分析需求与目标，输出完整的设计方案跟进并执行落地； 3.注重体验，持续推动产品优化体验与更新。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (135, N'智能体-高级产品策划深圳', 1, N'学历不限', N'社招', N'ECI   ', N'1.负责腾讯文档C端agent产品的智能体功能策划与设计，包括需求调研、功能规划、原型设计及需求文档输出； 2.深入理解用户需求，通过数据分析、用户反馈挖掘智能体功能优化点，提升用户体验和使用效率； 3.与研发、设计、测试等团队紧密协作，推动智能体功能从需求到上线的全流程落地； 4.跟进智能体功能上线后的效果评估，通过数据监控和用户反馈持续迭代优化； 5.关注行业动态和竞品趋势，为智能体功能的长期发展提供策略建议。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (136, N'腾讯营销HRBP-技术方向北京', 1, N'学历不限', N'社招', N'SEC   ', N'1.负责腾讯营销技术相关部门的HR政策、制度、体系与重点项目的落地与推动执行； 2.评估并明确组织与人才发展需求，驱动各方资源提供HR解决方案并持续演进； 3.提升管理干部管理能力，关注关键人才融入与培养，确保持续的沟通与反馈； 4.协助管理层进行人才管理、团队发展、组织氛围建设等，确保公司文化在所属业务领域的落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (137, N'CDG招聘经理（投资并购方向）深圳', 1, N'学历不限', N'社招', N'SEC   ', N'1.负责所属BG相关部门的社会招聘及校园招聘工作，制定有效的招聘策略并推动落地执行，保障人才开源、甄选和吸引； 2.负责相关部门人力资源市场分析，有效管理并优化招聘渠道； 3.参与招聘体系化建设，甄选相关优化项目，有效管理及优化招聘渠道。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (138, N'数字教育-产品策划-（就业方向）北京', 1, N'学历不限', N'社招', N'ECI   ', N'1）负责灵活就业撮合平台的产品策划及产品运营工作，包括产品方案制定，全流程参与和把控研发、落地运营和迭代； 2）挖掘真实需求，推动AI技术和工具在就业具体场景上的创新应用； 3）紧密配合业务方向和阶段需求，联动司内生态资源与行业内相关方，探索以产品为核心的模式方案，搭建相应的产品能力和运营策略，并推动落地实施； 4）参与平台运营，通过分级体系、奖惩制度、用户活动等运营策略，构建良性的用户体系和平台生态； 5）制定数据运营策略，通过数据埋点与漏斗监控，搭建指标分析体系，制定产品优化方向。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (139, N'工程档案', 9, N'本科', N'校招', N'CSI   ', N'职位类别：不限职位；单位性质：国企；规模：5000-10000人；行业：电力、热力生产和供应业
