INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (863, N'后端开发工程师-国际化达人营销平台', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责国际化达人营销平台的后端开发工作（如订单系统、账号体系、支付、触达等）； 2、应对全球化业务的挑战，解决分布式事务、数据一致性、服务治理等技术难题；持续对老旧系统进行重构与性能调优，提升系统的稳定性与扩展性； 3、探索LLM在业务场景和研发流程中的应用。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (864, N'直播后端研发工程师-视频云', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责直播流相关的后端技术方案的设计与实现； 2、服务端高可用架构的演进工作，包括但不限于架构优化、组件容灾、代码重构等工作； 3、大规模高并发系统的性能调优，长期优化服务端性能； 4、在直播CDN之间进行直播流的分配与调度，迭代调度算法实现不断升级的调度目标； 5、系统稳定性建设，包括高可用架构、故障响应、容灾演练、软件工程（CodeReview、文档建设、CI/CD）等。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (865, N'直播后端研发工程师-视频云', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责直播流相关的后端技术方案的设计与实现； 2、服务端高可用架构的演进工作，包括但不限于架构优化、组件容灾、代码重构等工作； 3、大规模高并发系统的性能调优，长期优化服务端性能； 4、在直播CDN之间进行直播流的分配与调度，迭代调度算法实现不断升级的调度目标； 5、系统稳定性建设，包括高可用架构、故障响应、容灾演练、软件工程（Code回顾、文档建设、CI/CD）等。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (866, N'高级后端研发工程师-Flow', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责豆包各类场景化Agent的后端研发，负责AI系统架构构建，快速搭建应用，持续优化产品体验、稳定性； 2、持续探索在各种场景下，利用AI能力增强产品体验，提升工程效率。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (867, N'后端开发工程师 - Seed 产品研发', 1, N'学历不限', N'社招', N'IEC   ', N'团队介绍：产品研发和工程架构-Seed 团队深耕大模型技术在场景中的创新应用，负责多款AI产品的工程研发 —— 包括豆包、飞书、豆包工作、豆包爱学、Gauth、猫箱等创新产品，覆盖消费级与企业级多个场景。我们致力于将大模型能力从 "生成内容" 推进到 "完成工作"，让 AI 服务用户日常与企业协作。你将面对多模态交互、工具调用可靠性、企业级数据安全等真实工程挑战，与团队一起推动 AI 生产力落地。 1、负责后端服务技术开发与架构演进相关工作： 1）负责模块的技术设计、开发与持续迭代，参与复杂业务场景下的系统建模与领域设计，构建高可用、高并发、可扩展的后端服务； 2）技术架构演进：参与系统架构优化，推动工程架构升级、性能调优与稳定性建设，解决技术难题； 2、参与AI技术在工作流引擎、智能项目管理等业务场景中的应用探索，将前沿AI能力融入产品体验，驱动业务创新； 3、持续优化研发流程、代码质量与工程实践，参与AI在研发流程中的探索与落地，推动团队工程能力提升； 4、负责系统的稳定性保障，快速定位解决问题，持续优化系统稳定性，以及故障响应和处理能力。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (868, N'后端开发工程师（ASM） - IT', 1, N'学历不限', N'社招', N'IEC   ', N'团队介绍：IT部门面向字节跳动员工提供全球IT技术支持。我们既负责企业内部IT基础架构的设计和优化，也肩负着保护企业信息安全，降低企业运营风险的使命；同时，IT团队还会直接面向字节跳动各业务线，承接企业级的网络、系统、终端、资产、服务台、多媒体、办公管理等多业务场景的研发需求，打造符合业界标准的商业化企业解决方案和产品，运用大数据和AI技术，提供更加自动化和智能化的企业技术服务。 1、参与推动负责IT部门企业级资产和服务管理平台和系统的研发工作； 2、独立负责一个中等复杂子系统，确保高质量交付、服务的性能和稳定性； 3、推动产品形态和业务发展迭代，能及时对业务方向和技术方案进行纠偏，并给出可落地的方案，对业务结果负责； 4、对开发流程和产品研发流程进行优化和迭代，保证项目进度，促进产品和研发合作； 5、改进产品的设计和架构，对模块进行合理拆解，确保架构的合理和先进性，并对技术难题有攻坚能力； 6、关注后端技术发展，能促进团队的技术氛围，并辅导团队中工程师帮助其成长。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (869, N'AI Agent后端开发工程师（AI垂直场景）-集团信息系统', 1, N'学历不限', N'社招', N'IRE   ', N'1、设计、构建并持续演进后端服务，通过性能分析、调优和代码质量改进确保系统的可维护性、可扩展性、可观测性与可靠性； 2、与产品、设计及跨职能团队合作，交付新功能并优化用户体验； 3、通过代码评审、架构指导和知识分享指导团队成员成长； 4、驱动中长期技术路线图，制定清晰的演进策略，并运用成熟方法解决复杂问题，帮助团队更高效地应对技术挑战。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (870, N'高级后端开发工程师-飞书文档', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责飞书文档/表格/Slide产品的后端需求开发； 2、负责飞书文档/表格/Slide架构优化，稳定性提升相关工作； 3、负责高质量的设计和编码，承担重点、难点的技术攻坚。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (871, N'后端开发工程师（智能客服）-TikTok', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责TikTok全球智能客服平台架构设计与后端研发，主导大模型在客服场景的全流程落地，包括全AI Agent、AI Copilot等智能化能力的落地，面向全球海量用户，日均数百万量级用户进线服务，打造极致高效、高满意度的下一代智能客服服务体系； 2、基于对业务的深入理解，深度参与业务全链路建模，持续优化客服流转效率、降低人工转接率、提升用户端CSAT指标； 3、深度参与产品迭代与复杂业务需求，结合优先级与业务紧急度进行合理拆解、技术方案选型、架构设计与高效交付，保障系统高可用、高性能、可扩展； 4、主导关键技术方案评审、技术文档沉淀、难点攻坚与存量架构持续优化，建设智能客服平台通用能力与技术底座。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (872, N'后端开发工程师（企业服务系统）-集团信息系统', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责采购、合同、内审等系统的后端研发工作，参与业务需求讨论、产品设计评审，高效高质量完成产品交付； 2、负责针对多个产品广泛共用的能力进行抽象、开发及架构优化工作，产出高质量的技术方案和代码，优化系统性能及稳定性； 3、负责LLM与Agent技术在业务系统中的应用，推动AI Coding落地。 1 2 3 4 5 168 联系我们? 相关网站? 候选人反馈平台 官网使用体验反馈 字节跳动 校园招聘 全球招聘 字节跳动 Seed ?? Hi，有什么可以帮你？ 我可以推荐岗位、查询投递进度、解答招聘相关问题。想从哪个开始？ 你的 AI 求职搭子来了 政策流程不了解、岗位不知道怎么选， 一个入口全搞定 线上咨询 政策、流程随时问，回答迅速又靠谱 个性化荐岗 上传简历、表达意向，秒懂并推荐你适合的岗位 稍后再说 立即体验
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (873, N'前端研发工程师-基础架构', 1, N'学历不限', N'社招', N'IEC   ', N'1、参与数据中心网络平台产品及工具服务的建设； 2、与产品经理、后端开发工程师等配合，完成平台的前端设计、开发、运维工作； 3、负责用户的前端体验优化，包括但不限于：易用性、展示效果、性能、安全等； 4、关注行业动态和趋势，配合研发团队，构建和完善内部平台。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (874, N'资深前端全栈专家 - Data AML', 1, N'学历不限', N'社招', N'IEC   ', N'团队介绍：Data AML是字节跳动的机器学习中台，为抖音/今日头条/西瓜视频等业务提供推荐/广告/CV/语音/NLP的训练和推理系统。为公司内业务部门提供强大的机器学习算力，并在这些业务的问题上研究一些具有通用性和创新性的算法。同时，也通过火山引擎将一些机器学习/推荐系统的核心能力提供给外部企业客户。 1、负责团队机器学习/深度学习业务系统的前端全栈架构设计、Agentic化建设AI原生产品系统、精准技术选型以及完善技术方案的制定，确保架构能够支撑产品的高并发、高性能需求； 2、主导前端全栈工程化建设，负责AI原生的大模型、机器学习AI平台及应用的建设，包括Web控制台、AI Agent平台、端侧SDK/CLI/APP等的前端界面、BFF中间层与后端服务的端到端架构设计和实现； 3、带领团队全力攻克技术难题，针对不同业务产品的特点制定并推行适应Agentic的技术开发规范和最佳实践，提升团队整体技术产出质量，通过控制它和Agent产品，持续提升产品的使用效率效果； 4、积极推动跨团队技术合作，与算法团队、产品团队紧密配合，深度参与重要技术决策，为各团队提供专业的技术咨询，促进技术协同发展，助力大模型至上的专业Agent、Studio产品应用的技术实现； 5、密切关注技术发展趋势，组织进行技术预研和创新实践，并在团队内有效进行技术分享，保持团队技术先进性，以适应不断迭代的机器学习业务和产品需求； 6、承担团队日常管理工作，包括任务分配、进度跟踪、绩效评估等；同时，悉心指导和培养团队成员，提升团队凝聚力和执行力；拥有出色的沟通协调能力，能顺畅地与不同团队进行协作。
