INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (877, N'前端开发工程师-抖音支付', 1, N'学历不限', N'社招', N'IEC   ', N'团队介绍：依托字节跳动强大的业务中台和技术中台能力，快速探索互联网全新的业务形态，寻找全新的用户需求，创造全新的业务场景，服务数亿用户。 1、自我驱动完成核心业务系统的前端研发工作； 2、优化前端体验，解决性能和交互难点； 3、参与前端工具链、通用服务、基础库、设计语言建设。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (878, N'前端研发工程师-算力基础设施', 1, N'学历不限', N'社招', N'IEC   ', N'1、参与多个网络管控平台及运维工具服务的设计与研发，打造AI驱动的网络可视化、智能运维与自动化管控系统； 2、积极推动多方协同，完成前端架构设计、核心模块开发、联调与持续运维，落地大模型交互、智能诊断、自动化运维等AI能力； 3、负责前端体验优化，包括易用性、展示效果、渲染性能、交互安全等，构建网络监控、流量分析、设备状态等数据可视化体系； 4、负责用户行为数据埋点、采集与分析，基于用户操作路径、页面访问、功能使用率等数据，输出分析结论并持续迭代产品交互与流程； 5、跟踪网络领域与前端AI技术趋势，结合业务场景和用户数据分析结果，优化平台操作效率与成本，参与构建智能化、自动化的内部平台。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (879, N'高级前端研发工程师-抖音音乐', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责抖音音乐人业务、音乐宣推、音乐AIGC方向的前端开发工作，包括用户产品端功能、大型活动等； 2、参与团队前端工程化体系建设，逐步提升研发效率、研发质量，通过前端技术的不断产出驱动业务的发展； 3、构建下一代AIGC音乐创作工具， 用前沿技术降低音乐创作门槛； 4、基于跨端和全栈技术探索高效开发迭代模式； 5、在跨端及全栈、音视频等技术方向进行核心难题攻坚。
