INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (882, N'前端开发工程师', 1, N'学历不限', N'社招', N'IEC   ', N'1、参与产品研发，包括 toC、toB、服务化等多个方向； 2、参与重点、难点的技术攻坚工作； 3、匹配大前端、大无线端技术要求。 1 2 3 4 5 56 联系我们? 相关网站? 候选人反馈平台 官网使用体验反馈 字节跳动 校园招聘 全球招聘 字节跳动 Seed ?? Hi，有什么可以帮你？ 我可以推荐岗位、查询投递进度、解答招聘相关问题。想从哪个开始？ 你的 AI 求职搭子来了 政策流程不了解、岗位不知道怎么选， 一个入口全搞定 线上咨询 政策、流程随时问，回答迅速又靠谱 个性化荐岗 上传简历、表达意向，秒懂并推荐你适合的岗位 稍后再说 立即体验
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (883, N'芯片ATE测试（芯片平台） - 芯片研发', 1, N'学历不限', N'社招', N'RIE   ', N'团队介绍：芯片平台是一个覆盖从逻辑综合到芯片投片、封装设计与仿真、回片测试、量产全流程的统一化芯片设计平台，提供支持多工艺、多项目的自动化设计流程及设计服务。平台整体划分为硅前、硅后、基础资源管理、IP 定制四大业务板块。 通过硅前 - 硅后全流程覆盖、IP 自主定制、基础资源统一管理的架构，芯片平台实现了从 RTL 到量产的端到端设计能力，支持多晶圆厂、多工艺节点，持续通过自动化提效与质量保障，为公司业务提供坚实的支撑。 1、与DFT工程师合作，完成SOC、MCU等相关芯片ATE测试方案的制定； 2、与供应商合作完成ProbeCard/LoadBoard/Socket的设计和制造； 3、完成CP和FT测试程序开发/调试/Release，保证ATE测试质量； 4、和其他团队合作，完成芯片特性化分析和Correlation验证； 5、测试数据分析，测试方法/覆盖率/成本/良率/交期等优化，解决测试中遇到的各种问题； 6、和QA工程师协作处理RMA，芯片故障和失效分析。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (884, N'芯片SLT测试工程师-芯片研发（上海）', 1, N'学历不限', N'社招', N'RIE   ', N'1、与EVB工程师合作，完成CPU、AI等大型SoC芯片SLT测试方案的制定，参与SLT测试软件需求分析和评审，提供测试方面的建议和意见； 2、负责设计SLT测试用例，包括芯片的功能测试、性能测试、兼容性测试、可靠性测试等； 3、负责调试部署SLT软硬件环境，并导入到工厂，维护量产SLT测试环境和测试数据，确保量产SLT测试工作的顺利进行； 4、分析SLT测试结果，识别和报告芯片系统级功能缺陷，跟踪其修复过程； 5、协助周边团队进行SLT失效芯片FA，提供必要的测试支持。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (885, N'芯片SLT测试工程师-芯片研发（深圳）', 1, N'学历不限', N'社招', N'RIE   ', N'1、与EVB工程师合作，完成CPU、AI等大型SoC芯片SLT测试方案的制定； 2、负责设计SLT测试用例，包括芯片的功能测试、性能测试、兼容性测试、可靠性测试等； 3、负责调试部署SLT软硬件环境，并导入到工厂； 4、分析SLT测试结果，识别和报告芯片系统级功能缺陷，跟踪其修复过程； 5、协助周边团队进行SLT失效芯片FA，提供必要的测试支持； 6、参与SLT测试软件需求分析和评审，提供测试方面的建议和意见，维护量产SLT测试环境和测试数据，确保量产SLT测试工作的顺利进行。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (886, N'高级测试工程师', 1, N'学历不限', N'社招', N'IEC   ', N'1、测试体系搭建：负责资产处置平台（包含C端、B端和运营端）整体质量保障，从0到1搭建测试体系，包含测试流程规范、用例管理、缺陷管理、质量度量指标、线上问题跟进等，制定核心链路的上线准入标准； 2、核心交易链路测试：设计拍卖竞价引擎专项测试（高并发下的出价顺序、延时规则、倒计时同步、异常场景下的数据一致性）和资金链路专项测试（保证金全生命周期、大额支付到账、退款准确性、多方资金对账）； 3、多端与多角色测试：负责C端（H5、PC、小程序）竞价流程一致性与多端兼容性测试；负责B端后台功能测试，验证多角色数据隔离与权限边界； 4、自动化与效能建设：搭建接口自动化测试框架并集成CI；建设竞价场景性能压测能力与线上质量监控；分析研发效能瓶颈，推动工具化、自动化改进方案落地； 5、团队协同：参与方案评审、架构设计，与业务、产品、研发紧密协作，确保测试目标与业务目标对齐，保障项目顺利推进与业务稳定运行。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (887, N'高级测试开发工程师-智能创作', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责抖音智能创作相关业务，为核心工程项目提供高质量交付工作； 2、构建适合相关业务发展的质量保障体系； 3、沉淀通用测试解决方案，负责关键技术专项建设，开发相关工具或服务提高测试效率； 4、解决测试过程中遇到的复杂技术问题，提炼相应的测试方法论、工具、服务、平台。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (888, N'芯片SLT测试工程师-芯片研发', 1, N'学历不限', N'社招', N'RIE   ', N'1、与EVB工程师合作，完成CPU、AI等大型SoC芯片SLT测试方案的制定； 2、负责设计SLT测试用例，包括芯片的功能测试、性能测试、兼容性测试、可靠性测试等； 3、负责调试部署SLT软硬件环境，并导入到工厂； 4、分析SLT测试结果，识别和报告芯片系统级功能缺陷，跟踪其修复过程； 5、协助周边团队进行SLT失效芯片FA，提供必要的测试支持； 6、参与SLT测试软件需求分析和评审，提供测试方面的建议和意见，维护量产SLT测试环境和测试数据，确保量产SLT测试工作的顺利进行。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (889, N'测试开发工程师', 1, N'学历不限', N'社招', N'IEC   ', N'1、主要负责公司数据平台部门自动化测试体系建设及推广； 2、参与构建自动化测试平台、性能测试平台、持续集成平台； 3、参与各种测试工具研发，效率工具研发； 4、负责测试用例编写、性能测试、压力测试、高可用测试（提升平台稳定性、可用性、核心性能)。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (890, N'测试开发专家 - TikTok 搜索', 1, N'学历不限', N'社招', N'IEC   ', N'团队介绍：TikTok搜索团队致力于为用户提供精准高效的搜索工具，创造良好的搜索体验，提升信息流动的效率，同时高价值的搜索流量也能带来商业化价值，为TikTok生态内的其他业务提供高效的入口，支持内容生态的发展，提升中尾部视频的消费力量。 你可以有机会参与核心业务功能的开发工作，接触到第一线的用户，我们期待你的加入！ 1、负责TikTok搜索业务的质量保障，测试技术、工具和平台创新； 2、能够快速拉通各种项目测试体系建立、测试流程、测试实施、质量和风险控制； 3、推进和改进各端的测试能力提升，落地自动化机制，持续推进测试效率提升； 4、营造良好的质量氛围，提升研发团队的质量意识，不断推动质量的建设。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (891, N'AI测试开发工程师 - TikTok内容安全平台', 1, N'学历不限', N'社招', N'IEC   ', N'团队介绍：国际化内容安全平台团队致力于为字节跳动国际化产品的用户维护安全可信赖环境，通过开发、迭代机器学习模型和信息系统以更早、更快发掘风险、监控风险、响应紧急事件，以人工智能技术支持业务发展，力求更高效、更敏捷、更全能地维护站内生态安全。 1、负责国际化产品内容安全审核相关平台的质量保障工作，覆盖服务端、平台系统及业务链路，保障产品质量、稳定性和线上交付效率；建设和完善平台系统质量保障体系，结合自动化测试、稳定性测试、专项质量建设等手段，持续提升测试效率、测试覆盖率及风险发现能力； 2、探索AI在质量保障和测试领域的应用，结合大模型、Agent、AI Coding等技术，建设智能化测试能力，包括测试用例生成、测试数据构造、风险分析、缺陷定位、自动化测试生成等场景，提升测试效率和质量保障能力； 3、负责AI相关业务及内容安全场景的测试与质量评估，探索AI模型/Agent的评测方法和测试体系，包括效果评测、场景评测、稳定性评测、安全性评测等，持续完善AI产品质量保障能力； 4、探索和落地SDT（场景驱动测试）等新型测试方法，结合业务场景、用户行为及线上风险，构建端到端测试场景和风险模型，提升复杂业务场景下的问题发现能力； 5、深入发掘和分析业务质量问题及线上风险，通过质量专项、测试工具、监控及自动化能力建设持续提升产品线上质量和风险防控能力，跟踪分析线上问题并定位根因，从测试方案、质量体系、稳定性建设等维度制定改进措施推动质量问题闭环，跨国家、跨地区协同研发、产品、运营及国际团队，高质量完成全球项目交付。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (892, N'资深测试开发工程师-搜索', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责搜索方向的质量保障，测试技术、工具和平台创新； 2、能够快速拉通大中型项目测试体系建立、测试流程、测试实施、质量和风险控制； 3、推进和改进各端的测试能力提升，落地自动化机制，持续推进测试效率提升； 4、营造良好的质量氛围，提升研发团队的质量意识，不断推动质量的建设。 1 2 3 4 5 136 联系我们? 相关网站? 候选人反馈平台 官网使用体验反馈 字节跳动 校园招聘 全球招聘 字节跳动 Seed ?? Hi，有什么可以帮你？ 我可以推荐岗位、查询投递进度、解答招聘相关问题。想从哪个开始？ 你的 AI 求职搭子来了 政策流程不了解、岗位不知道怎么选， 一个入口全搞定 线上咨询 政策、流程随时问，回答迅速又靠谱 个性化荐岗 上传简历、表达意向，秒懂并推荐你适合的岗位 稍后再说 立即体验
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (893, N'豆包大模型算法工程师-火山方舟', 1, N'学历不限', N'社招', N'IRE   ', N'1、负责改进RL训练系统，包括基于Ray的RL Trainer功能拓展、Rollout/采样策略探索、Reward系统集成、Agent Loop复杂任务下轨迹管理等； 2、负责大模型SFT/RL训练性能和稳定性优化，支持Reasoning，Agent，VLM等各类Post-Training任务； 3、探索前沿大模型算法和训练技术，包括Off-Policy RL训练效果和效率、SRFT、OnPolicy Distillation等。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (894, N'NLP算法工程师-抖音对话机器人', 1, N'学历不限', N'社招', N'IRE   ', N'负责抖音对话机器人场景中NLP技术的研发与应用，研究包括传统NLP技术、LLM技术在聊天机器人领域基础技术支持和落地应用。主要工作方向包括： 1、负责对客服、角色化对话机器人算法方向的通用NLP基础能力建设，包括但不限于数据建设、模型训练推理框架迭代、维护模型评估指标体系、建设通用NLP模型； 2、支持LLM、MLLM方向的新技术研究和落地应用，支持指令微调、强化学习相关算法需求； 3、建设基于LLM/MLLM技术的新一代的智能客服机器人，探索建设数字人技术在抖音落地应用。
