INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (900, N'豆包大模型算法工程师-火山方舟', 1, N'学历不限', N'社招', N'IRE   ', N'1、发现优化大模型的简单、普适的想法，并应用到各个规模的模型中提升效果； 2、推进数据建设、指令微调、偏好对齐、继续预训练等模型优化方面的工作，提高模型质量和适应性； 3、探索复杂指令、长上下文、多轮对话下，大模型更为复杂的理解、推理和生成能力； 4、基于语言处理、内容创作、教育指导、角色扮演、复杂Agent、AI搜索和工具、代码助手等服务和应用优化模型效果； 5、推进大模型效果评估，尤其是复杂场景（多轮对话、开放领域）评估集建设和自动化评估能力建设； 6、深入研究和探索大模型在ToB企业服务中的更多使用场景，拓展模型的应用范围，如搜索、推荐、广告、创作、客服和办公等各类场景。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (901, N'广告激励算法工程师-Data', 1, N'学历不限', N'社招', N'IRE   ', N'1、负责激励广告核心算法建设，包括广告召回、排序、出价、激励金额决策、用户价值预估、点击率预估等方向； 2、设计金币/现金激励策略，优化用户广告观看率、留存、活跃、转化及平台长期收益； 3、构建大规模用户行为模型，理解不同用户在激励、广告内容、频控、时机等因素下的响应差异。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (902, N'豆包大模型Agent算法工程师 - 火山方舟', 1, N'学历不限', N'社招', N'IRE   ', N'团队介绍：火山方舟是火山引擎推出的一站式大模型服务平台，是中国大模型市场产品和份额领跑者。平台提供模型推理、评测、精调等全流程服务。方舟搭载了豆包及业界主流大模型，提供丰富的插件生态和AI应用开发服务，并通过稳定可靠的安全互信方案、专业的算法技术服务，全方位保障企业级AI应用落地。 1、参与火山方舟Managed-Agent相关的算法研发工作，参与方舟自有Harness的技术架构选型、设计、优化； 2、优化方舟自有Harness，包括但不限于Harness的运行模式、Built-in Tools、Context机制、multi-Agent协作调度、智能的辅助能力（模型选择、Advisor、Grader、Ralph loop等等）； 3、和评测团队一起构建面向Harness迭代的Agent评测，构建全面、有效的Agent Harness端到端评测； 4、定义和实现Harness领域的前沿创新，与模型团队深度合作，参与实现模型与Harness的共同进化，从Harness的角度实现Seed Model和Harness与模型的深度适配。 1 2 3 4 5 355 联系我们? 相关网站? 候选人反馈平台 官网使用体验反馈 字节跳动 校园招聘 全球招聘 字节跳动 Seed ?? Hi，有什么可以帮你？ 我可以推荐岗位、查询投递进度、解答招聘相关问题。想从哪个开始？ 你的 AI 求职搭子来了 政策流程不了解、岗位不知道怎么选， 一个入口全搞定 线上咨询 政策、流程随时问，回答迅速又靠谱 个性化荐岗 上传简历、表达意向，秒懂并推荐你适合的岗位 稍后再说 立即体验
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (903, N'数据分析师-番茄小说', 1, N'学历不限', N'社招', N'IEC   ', N'团队介绍：番茄小说是抖音在2019年推出的免费阅读产品，致力于为读者提供优质的阅读体验；番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。 1、负责番茄小说等相关业务的数据分析工作； 2、分析各项影响产品提升与增长的因素，结合业务方向，给出可落地的整体产品优化方案； 3、与产品/运营/研发等配合，推进优化方案落地执行，带来业务的实际提升增长； 4、负责业务上各类A/B实验设计与分析，产品优化效果、市场活动分析评估等工作； 5、建设业务分析模型，并不断评估和优化。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (904, N'数据分析师-番茄小说', 1, N'学历不限', N'社招', N'IEC   ', N'团队介绍：番茄小说是抖音在 2019 年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。 1、负责番茄小说、番茄畅听、漫画等相关业务的数据分析工作； 2、分析各项影响产品提升与增长的因素，结合业务方向，给出可落地的整体产品优化方案； 3、与产品/运营/研发等配合，推进优化方案落地执行，带来业务的实际提升增长； 4、负责业务上各类?A/B?实验设计与分析，产品优化效果、市场活动分析评估等工作； 5、建设业务分析模型，并不断评估和优化。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (905, N'数据分析师-抖音', 1, N'学历不限', N'社招', N'IEC   ', N'1、完成抖音业务生态、推荐、产品相关的数据分析工作，对业务表现进行敏捷有效的监控与评估，管理业务目标达成进度； 2、梳理和分析业务增长问题与难点，提出假设并通过数据论证，输出业务策略和建议； 3、理解业务指标变化并建立常态化归因机制，基于归因结论为后续业务迭代提供方向和指引； 4、专项分析课题，深度参与分析项目的推进全过程； 5、可自闭环完成从分析发现到策略落地的全过程。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (906, N'今日头条数据分析师', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责今日头条业务的数据分析工作； 2、分析各项影响产品提升与增长的因素、各项业务细节，结合业务方向，给出可落地的整体的产品优化方案； 3、与产品/运营/研发等配合，推进优化方案落地执行，带来业务的实际提升增长； 4、负责业务上各类A/B实验设计与分析，产品优化效果评估，市场活动分析评估，核心指标异动分析，客户端版本效果评估等工作； 5、负责业务上特化模型的建设工作。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (907, N'数据分析师', 1, N'学历不限', N'社招', N'IEC   ', N'从数据侧入手，深度参与财经部门各业务的早期孵化和精细化运营，包括数仓及报表设计、数据实验执行及复盘、业务目标建模及测算等，具体： 1、与战略团队协作，从宏观视角完成业务规划及目标制定，提供内、外部数据测算支持，明确核心商业模型、评价业务发展情况； 2、与产品及运营团队配合，从微观角度，通过各类数据实验、人群分析，不断优化产品流程，给出可落地的优化方案及建议，并持续推进，拿到实际结果； 3、与数仓、研发团队合作，设计业务线整体的指标字典以及数仓主题逻辑，提高数据利用效率，为整体数据质量负责。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (908, N'番茄小说数据分析师', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责字节泛文娱长内容赛道相关业务的数据分析工作，对接国内、国际化多业务线内容分析与数据建设； 2、深入理解内容生态，通过数据挖掘建立优质内容和创作者评估标准，协助迭代平台内容策略； 3、定位内容和创作者冷启问题，优化冷启效率；基于容器实验等对内容价值进行评估，分析内容建设的高杠杆投入方向，并为内容引入提供建议； 4、用机器学习方法建立业务模型，并不断优化模型效果，提升业务指标，例如：内容收入预测、ROI预测模型等、优质创作者识别等； 5、与产品、运营、研发等配合，推动分析结果与模型结果落地，直接提升业务指标。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (909, N'资深数据分析师-财经', 1, N'学历不限', N'社招', N'IEC   ', N'1、负责信贷业务增长、产品链路、盈利等方向的数据分析工作； 2、理解业务环节和用户，如授信、首贷、留存、还款等，建立完善的业务指标体系，通过数据手段定位业务瓶颈，挖掘增长机会； 3、建立严谨的A/B测试方案和因果推断模型，科学评估各项增长动作的真实收益； 4、与业务团队合作，对增长策略进行优化迭代，包括但不限于权益推荐、流量分配、营销物料推荐； 5、与产品、运营、算法等团队配合，推动分析结果与模型结果落地，带来业务指标增长。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (910, N'数据分析师（红果短剧方向）-番茄小说', 1, N'学历不限', N'社招', N'IEC   ', N'团队介绍：番茄小说是抖音在2019年推出的免费阅读产品，致力于为读者提供优质的阅读体验。番茄小说拥有海量正版小说，涵盖言情、都市、玄幻、悬疑等主流网文类型，以及大量热剧原著和经典出版物，支持用户看书、听书。 1、负责红果短剧等相关业务的数据分析工作； 2、分析各项影响产品提升与增长的因素，结合业务方向，给出可落地的整体产品优化方案； 3、与产品/运营/研发等配合，推进优化方案落地执行，带来业务的实际提升增长； 4、负责业务上各类A/B实验设计与分析，产品优化效果、市场活动分析评估等工作； 5、建设业务分析模型，并不断评估和优化。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (911, N'数据分析师（效果与创作方向）-抖音', 1, N'学历不限', N'社招', N'IEC   ', N'1、参与抖音效果与创作方向的数据分析工作，与业务紧密配合，寻求新的增长机会和突破点；通过前沿的AIGC技术落地，相机产品的迭代，以及推荐算法的优化提升用户在抖音内的创作体验； 2、深入理解业务逻辑和用户需求，量化业务目标和关键过程指标，搭建数据监控体系，有效描述业务进展、及时洞察异动，并解读归因； 3、高效支持业务需求迭代，基于需求AB分析等，总结提炼经验，提出改进建议，提升业务迭代效率； 4、围绕业务目标，展开主题分析，描述业务现状，洞察问题和机会点；并能给出具体的解决方案和推进产品策略有效落地。 1 2 3 4 5 580 联系我们? 相关网站? 候选人反馈平台 官网使用体验反馈 字节跳动 校园招聘 全球招聘 字节跳动 Seed ?? Hi，有什么可以帮你？ 我可以推荐岗位、查询投递进度、解答招聘相关问题。想从哪个开始？ 你的 AI 求职搭子来了 政策流程不了解、岗位不知道怎么选， 一个入口全搞定 线上咨询 政策、流程随时问，回答迅速又靠谱 个性化荐岗 上传简历、表达意向，秒懂并推荐你适合的岗位 稍后再说 立即体验
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (912, N'数据产品经理-火山引擎', 1, N'学历不限', N'社招', N'ECI   ', N'1、负责数据系统底层/应用层/分析层的数据服务，为产品方向、增长策略提供数据支持； 2、根据业务需求对用户行为分析系统/AB试验后台等数据产品优化，提高数据分析效率； 3、参与到整个需求调研、产品设计、文档编纂，开发跟进、功能测试、用户反馈、迭代优化环节； 4、服务对象除公司内部以外，还包括为外部合作公司提供商业产品级服务。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (913, N'AI数据产品经理 - 抖音电商', 1, N'学历不限', N'社招', N'ECI   ', N'团队介绍：抖音电商以“总能发现好东西”为主张，致力于成为用户发现丰富好物的首选平台。众多抖音创作者通过短视频、直播、商城等丰富的形式，给用户提供更个性化、更生动、更高效的消费体验。同时，抖音电商积极引入优质合作伙伴，为商家变现提供多元的选择。 1、负责抖音电商全域数据产品体系设计，面向品牌、商家、管理层及运营小二等多角色，搭建面向业务场景的指标体系、评估标准、问题诊断能力和智能决策能力； 2、推动AI+数据产品创新，将大模型、智能Agent等AI能力融入数据产品，实现智能取数、智能问数、自动化报告、智能决策建议等场景，降低用数门槛，提升决策效率； 3、深度挖掘业务场景，沉淀业务数据分析场景，支持和赋能用户使用数据决策； 4、主导产品全生命周期管理，完成需求分析、产品规划、原型设计、项目管理、效果验收及持续迭代，确保产品高质量落地； 5、构建跨团队协同机制，联动业务、算法、技术、运营等团队，推动数据能力与AI技术的业务化应用，对产品的使用渗透率和业务价值负责。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (914, N'高级数据产品经理 - BI', 1, N'学历不限', N'社招', N'ECI   ', N'1、负责BI平台规划&设计，独立完成产品调研、方案设计以及协调各方资源推动产品上线； 2、关注业界内BI类产品以及大数据开发治理产品的动态， 负责大数据处理加工模块的整体规划设计，提供客户一站式数据处理分析可视化平台； 3、参与数据产品的运营工作，包括产品的推广、培训、文档撰写等环节，辅助各业务线/职能部门接入&完善BI门户； 4、参与ToB的产品定位和规划。调研行业发展方向，形成产品规划。对接客户需求，评估需求可行性和优先级，推进需求落地，最终顺利产生价值。
