INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (917, N'数据产品经理 — BI方向', 1, N'学历不限', N'社招', N'ECI   ', N'1、负责BI平台规划&设计，独立完成产品调研、方案设计以及协调各方资源推动产品上线； 2、关注业界内BI类产品以及数据可视化工具的动态， 提供更高效、更完善的BI产品支持分析决策； 3、承担数据产品的运营工作，包括产品的推广、培训、文档撰写等环节，辅助各业务线/职能部门接入&完善BI门户； 4、根据各业务战略方向，调整产品规划，拓展产品使用场景，提供智能解决方案。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (918, N'数据产品经理 - BI方向', 1, N'学历不限', N'社招', N'ECI   ', N'1、负责BI平台规划&设计，独立完成产品调研、方案设计以及协调各方资源推动产品上线； 2、关注业界内BI类产品以及数据可视化工具的动态， 提供更高效、更完善的BI产品支持分析决策； 3、承担数据产品的运营工作，包括产品的推广、培训、文档撰写等环节，辅助各业务线/职能部门接入&完善BI门户； 4、根据各业务战略方向，调整产品规划，拓展产品使用场景，提供智能解决方案。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (919, N'AI数据产品经理-商业数据平台', 1, N'学历不限', N'社招', N'ECI   ', N'1、负责大语言模型在广告业务的知识问答、取数、找数、数据分析等场景的AI数据产品孵化和应用，制定产品策略和规划； 2、在广告业务场景下，与前台产品深度合作，运用RAG问答、Agent编排、AI分析解读等能力从功能和调优上高度参与，对应用效果负责； 3、基于广告业务场景的理解，进行相关Agent应用的搭建，从场景中抽象沉淀成AI开放能力上，并完成能力的运营和接入拓展； 4、协调跨多职能团队合作，协同研发、前台产品团队提升场景可用性，保证项目高质量的实现和交付； 5、及时主动掌握行业最新动态以及底层模型的能力边界，对AI的可能性探索有热情，为产品创新提供思路。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (920, N'数据产品专家-用户行为分析方向', 1, N'学历不限', N'社招', N'ECI   ', N'字节跳动用户行为分析（UBA）平台是支持全公司业务分析和用户增长的数据产品，用户覆盖抖音/直播/西瓜视频/今日头条/游戏/教育等公司内所有高速发展的业务。 1、负责数据产品的方向性规划与推进落地、以及通过用户服务体系建立与业务方的强连接； 2、负责产品模块的设计，独立完成用户调研、方向规划、资源协调与项目推进等； 3、关注业内先进产品的动态、深入公司各业务线调研业务场景和使用反馈； 4、根据调研和公司策略，完善产品规划、拓展产品场景，提升在对业务支出的深度和广度； 5、组织数据产品的运营工作，包括产品的推广、培训、文档撰写、用户反馈、场景收集等各方面工具。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (921, N'数据产品经理-商业创新方向', 1, N'学历不限', N'社招', N'ECI   ', N'1、收集、洞察、抽象行业客户需求，挖掘新的商业模式，并制定高质量的产品规划； 2、与增长营销套件产品和解决方案团队保持深度协同，推动新商业模式在金融、汽车、泛互联网、通用等行业的落地； 3、负责营销平台相关功能的设计和创新，以及制定合理的迭代节奏和版本计划； 4、收入导向，对市场发展方向、集团动态、新商业模式保持关注，并协同相关方推进产品商业化规模扩大。 1 2 3 4 5 582 联系我们? 相关网站? 候选人反馈平台 官网使用体验反馈 字节跳动 校园招聘 全球招聘 字节跳动 Seed ?? Hi，有什么可以帮你？ 我可以推荐岗位、查询投递进度、解答招聘相关问题。想从哪个开始？ 你的 AI 求职搭子来了 政策流程不了解、岗位不知道怎么选， 一个入口全搞定 线上咨询 政策、流程随时问，回答迅速又靠谱 个性化荐岗 上传简历、表达意向，秒懂并推荐你适合的岗位 稍后再说 立即体验
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (922, N'HCI人机交互设计师-PICO', 1, N'学历不限', N'社招', N'IAE   ', N'1、参与XR产品对人机交互的探索与研究，包括但不限于通用型交互，多模态交互，业务场景交互； 2、配合产品路线，搭建与优化交互系统设计与框架，积累人机交互范式，建立人机交互设计系统； 3、探索新型的硬件与交互方案，提出创新交互概念，给出工程层面的实现策略，负责最终的Demo以及工程落地实现； 4、从用户角度出发，优化已有人机交互体验，提出算法和策略，保证交互模型的落地，洞察人机交互的提升点，并持续优化可用性。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (923, N'创新硬件人机交互设计-AI创新业务', 1, N'学历不限', N'社招', N'IAE   ', N'1、参与创新消费智能产品的全链路人机交互设计，覆盖硬件实体交互、软件界面交互、多端联动体验，打造易用、有温度的一致性用户体验； 2、参与产品前期的用户研究与场景挖掘，挖掘用户痛点与潜在需求，输出交互设计洞察，制作交互及概念原型，支撑产品定义与需求决策； 3、跟踪行业前沿交互技术与趋势，如多模态交互、空间计算、AI Agent交互等，探索创新交互场景，为产品体验升级提供方向与落地路径； 4、协同产品、硬件研发、软件研发、视觉设计、用户研究等跨部门团队，推动设计方案的落地，解决落地过程中的体验与技术平衡问题。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (924, N'游戏交互设计师（二次元向） - Bluesea Studio', 1, N'学历不限', N'社招', N'IAE   ', N'团队介绍：Bluesea工作室成立于2024年8月，当前涉足卡牌/RPG/SLG/竞技等多个品类，已经上线的游戏《放置少女》，各类新产品已蓄势待发。欢迎加入我们！ 1、参与游戏整体交互体验设计，根据游戏玩法和策划需求，完成信息架构、操作流程、界面布局、交互原型等设计，能够独立负责复杂系统的交互设计； 2、深入理解游戏玩法和玩家需求，能够发现和分析体验问题，提出合理的交互解决方案，持续优化游戏体验； 3、与UI、VX、重构、策划、程序等团队紧密配合，共同优化需求方案，产出具备市场竞争力的游戏UX设计，提升玩家体验； 4、跟进交互设计在最终游戏中的实现效果，及时发现并推动解决体验问题，保证最终实现效果和设计方案的一致。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (925, N'人机交互设计-AI创新业务', 1, N'学历不限', N'社招', N'IAE   ', N'1、负责创新型AI硬件的全链路人机交互设计，覆盖：用户场景挖掘、差异化人机交互创新探索、软硬件原型制作、产品定义与硬件架构设计等； 2、参与产品前期的用户研究，洞察用户的痛点与潜在需求，通过快速原型验证关键假设，推动形成具有吸引力和长期使用价值的软硬件产品方案； 3、协同软硬件研发、交互设计、工业设计、算法等角色及跨部门团队，参与可行性评估、原型验证与迭代，推动软硬件一体设计方案的落地； 4、跟踪行业前沿交互技术与趋势，如：多模态交互、长期记忆、感知策略、AI Agent交互等，探索差异化人机交互创新，为产品提供新的可能性与落地路径。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (926, N'创新硬件人机交互设计-AI创新业务', 1, N'学历不限', N'社招', N'IAE   ', N'1、参与创新消费智能产品的全链路人机交互设计，覆盖硬件实体交互、软件界面交互、多端联动体验，打造易用、有温度的一致性用户体验； 2、参与产品前期的用户研究与场景挖掘，挖掘用户痛点与潜在需求，输出交互设计洞察，制作交互及概念原型，支撑产品定义与需求决策； 3、跟踪行业前沿交互技术与趋势，如多模态交互、空间计算、AI Agent交互等，探索创新交互场景，为产品体验升级提供方向与落地路径； 4、协同产品、硬件研发、软件研发、视觉设计、用户研究等跨部门团队，推动设计方案的落地，解决落地过程中的体验与技术平衡问题。
