INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (928, N'资深交互设计师（店铺方向）-抖音电商', 1, N'学历不限', N'社招', N'IAE   ', N'1、负责抖音电商店铺的C端产品体验设计工作，包含多类型的店铺框架设计，主导大型设计体验及优化工作，从用户和商家平台经营诉求多角度出发，构建店铺体验设计； 2、善于发掘和探索业务机会点，通过用户研究、数据分析挖掘场景痛点，协同业务完成方案共建和设计提案；敏锐的用户视角与分析力，基于架构提出体验提升建议，输出可落地、具可行性的产品解决方案； 3、完成重点项目的全局改版工作，具备项目管理和推动能力，高效完成符合目标的设计产出； 4、能够综合运用市场分析、用户研究、数据分析等多种方法，对设计产出进行评估、复盘和分享。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (929, N'C端UX设计师（AI方向）-TikTok Shop', 1, N'学历不限', N'社招', N'IAE   ', N'1、AI产品体验设计：负责AI电商导购（如电商AIGC内容生成、对话式购物助手等）的端到端用户体验设计，包括用户研究、概念发散、信息架构、交互设计和UI视觉落地； 2、定义AI设计模式：探索并建立适用于电商场景的AI设计语言与组件库（如多模态结果展示、对话式交互等），为团队树立设计标准； 3、跨职能协同创新：与产品经理、AI工程师、数据科学家紧密合作，将复杂的AI技术能力转化为直观、可信赖、甚至愉悦的用户价值； 4、用户研究：规划并执行可用性测试与用户访谈，深度理解用户在AI产品前的困惑、信任与期望，基于数据和用户反馈，持续驱动设计优化与迭代； 5、前瞻性探索：持续追踪AI/ML领域的设计趋势与技术突破，主动发起创新设计项目，探索AI在提升电商转化、满意度与粘性方面的全新可能性。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (930, N'UX设计师-AI创新业务', 1, N'学历不限', N'社招', N'IAE   ', N'1、负责AI产品和系统级软件的交互设计； 2、以行业最领先的交互体验为目标，高质量完成业务需求； 3、完成具备前瞻性业务价值的专业交互研究； 4、完成具备业务价值、完成度高的概念设计。
