INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (932, N'用户研究AI Agent产品-抖音', 1, N'学历不限', N'社招', N'IRE   ', N'1、负责字节跳动用户研究Agent的产品迭代全流程管理，深度洞察挖掘内外部用户需求（包括用户研究/业务方/外部客户）和行业前瞻方向，制定产品路径图和功能迭代路径，高效推进产品方案落地； 2、制定并持续迭代模型产出/任务执行效果评测体系，根据评测结果对模型输出产物质量进行持续跟踪和优化，提升产品可用性； 3、跨团队推动UED、研发、测试到上线的项目管理等全流程工作的开展，合作完成产品目标和核心指标； 4、分析产品寻找差异化突破点，评估现有产品的商业化潜力，制定从内部工具向商业化产品转型的可行性方案。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (933, N'用户研究专家-PICO（北京/上海）', 1, N'学历不限', N'社招', N'IAE   ', N'1、配合产品IPD流程的相关节点，开展市场细分、目标人群洞察、场景需求挖掘、产品前后测等全流程的用户研究项目； 2、基于对业务规划和用户的理解主动提出研究课题，把控项目节奏和调研质量，完成用户研究到洞察的转化，将用户研究的基础资料转化为产品改善或创新的建议。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (934, N'用户研究分析师-抖音（上海）', 1, N'学历不限', N'社招', N'IAE   ', N'1、负责短视频、社交、投稿等业务的国内用户研究工作； 2、能独立支持业务，主动跟进业务方向策略及进展，完成业务生态内各类用研项目的需求分析、方案设计、项目执行，并输出具有较强落地性的专业研究报告、并深度参与研究项目的落地推进工作。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (935, N'游戏资深用户研究员 - 游戏业务管理办公室', 1, N'学历不限', N'社招', N'IAE   ', N'团队介绍：游戏业务管理办公室主要是为游戏业务的管理者和项目团队提供经营管理、研发管理、用户研究、商业分析、合规管理、外包管理等支持工作。 1、负责一至两个游戏产品或明确研究模块的用户研究工作，持续理解产品阶段、目标用户、核心体验和关键版本节点； 2、根据概念验证、玩法原型、版本测试、上线准备及运营迭代等不同阶段，识别研究问题并制定合适的研究方案； 3、独立完成需求澄清、研究设计、用户招募与执行管理、数据分析、报告撰写和结果跟进； 4、综合运用深度访谈、可用性测试、概念测试、问卷调研等方法，为产品团队提供可靠的玩家证据； 5、与策划、产品、运营、数据等团队紧密合作，将研究发现转化为清晰、可执行的产品建议，并跟进研究结论的应用； 6、持续沉淀所负责产品的玩家认知、体验问题和历史研究结论，建设可复用的研究资产。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (936, N'用户研究分析师-抖音社区', 1, N'学历不限', N'社招', N'IAE   ', N'1、负责抖音内容消费体验、社区互动、圈层文化方向的国内用户研究工作，能独立支持业务完成落地性强的专项研究，承担各类用户研究项目的需求分析、方案设计、项目执行、报告产出，并推动业务落地策略获得收益； 2、针对推荐类个性化内容消费，能够理解业务逻辑，擅用产品化研究方法、结合数据分析等方式设计研究，定位推荐分发关键问题诊断与策略验证； 3、负责前瞻战略类分析，通过行业分析、商业分析、定性定量调研等手段，从用户底层需求、市场竞争格局等综合视角出发洞察与产品的关键竞争场景与产品机会点，为中长期方向提供判断依据。
