INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (940, N'用户研究分析师-抖音内容生态与体验', 1, N'学历不限', N'社招', N'IAE   ', N'1、负责抖音内容体验方向重点生态问题的长期度量与监测体系建设，持续完善指标体系、数据口径和归因机制，及时识别指标水位及生态变化趋势，形成对业务有价值的分析结论，推动相关策略落地； 2、深入理解业务场景与运作逻辑，能够灵活运用定性与定量调研、业务客观数据分析、社媒及市场数据分析、AI辅助分析等多种研究方法，识别并解释业务需要关注的核心问题，形成清晰的业务判断并提出可落地建议； 3、与数据科学（DS）、产品、运营、算法等团队紧密协作，结合用户主观反馈与客观行为数据，从用户和平台等不同视角综合分析问题，推动各方形成共识并促进研究结论落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (941, N'商家策略分析与用户研究专家-生活服务', 1, N'学历不限', N'社招', N'IAE   ', N'1、洞察商家：通过对商家定性和定量等方式调研，深入理解生活服务商家的经营逻辑与盈利模式，获取对商家真实需求、问题场景与决策路径的一手洞察； 2、理解业务：快速理解平台业务模式、产品与策略的运作逻辑，把握其设计意图与增长路径； 3、识别问题与机会：结合对商家的洞察与对业务的理解，拆解业务模式与产品策略，定位业务机制与产品逻辑中的问题，并识别潜在的增长机会； 4、产出决策建议：综合运用定性研究与定量分析等各类研究手段，产出可落地、可影响业务核心指标的决策建议； 5、独立视角审视与推动落地：站在公司视角独立审视业务问题与机会，在关键决策节点提供客观判断，并跨部门推动结论被采纳与落地。 1 2 3 4 5 117 联系我们? 相关网站? 候选人反馈平台 官网使用体验反馈 字节跳动 校园招聘 全球招聘 字节跳动 Seed ?? Hi，有什么可以帮你？ 我可以推荐岗位、查询投递进度、解答招聘相关问题。想从哪个开始？ 你的 AI 求职搭子来了 政策流程不了解、岗位不知道怎么选， 一个入口全搞定 线上咨询 政策、流程随时问，回答迅速又靠谱 个性化荐岗 上传简历、表达意向，秒懂并推荐你适合的岗位 稍后再说 立即体验
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (942, N'人力资源业务合作伙伴-云基础（北京/上海）', 1, N'学历不限', N'社招', N'SEC   ', N'1、支持字节跳动云基础技术团队，了解业务状况和团队运作状况，理解业务目标，提供符合业务团队需求的相关人力方案； 2、执行所支持部门的招聘、企业文化、培训等人力资源工作，协助业务部门提升组织绩效； 3、结合公司人才和组织发展框架，清晰胜任力素质模型，设计人员成长路径及人员培养方案，有效制定和实施人才发展计划并跟进实施； 4、为团队的发展提供支持，应用专业理论、方法、工具，为业务团队提供全方位解决方案，包括招聘、培训、绩效、员工关系等人力资源工作； 5、推动业务团队企业文化的建设和落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (943, N'HRBP-抖音（上海）', 1, N'学历不限', N'社招', N'SEC   ', N'1、深入了解抖音业务和组织，深入理解业务战略并促进人力资源战略在业务部门的有效实施； 2、负责抖音业务部门的团队搭建，在人才的选、育、用、留上给予业务部门有效的建议，有效制定和推动人才发展计划并落地实施； 3、洞察抖音组织和团队存在的问题，为业务团队提供全方位的人力资源解决方案，包括招聘、培训、绩效、员工关系等，并推动方案落地； 4、推动组织及团队氛围建设，推动公司文化建设，以支持业务的高速发展。
