INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (952, N'行政经理（深圳）', 1, N'学历不限', N'社招', N'SEC   ', N'1、负责楼宇内行政全模块运营管理，做好员工各项服务，办公区空间、环境的品质管理，含装修验收、搬迁、入住前期筹备及日常运营（如前台、保洁、绿植、设施、康体中心等），持续提升工作环境及服务体验； 2、负责楼宇全品类供应商管理及考核、合规化建设；贯彻行政部制度规范及SOP并在日常运营中结合实际反馈并提出优化建议； 3、负责楼宇行政费用管控及运营数据分析，制定可执行的管控策略，推动降本增效；配合业务完成各类活动、项目等需求落地，根据需求给出高质量方案并完成交付； 4、对设施相关系统运营管理有基本了解，如暖通、电气、电梯、给排水、照明、基础小规模改造等； 5、沟通协调跨部门资源、妥善应对各类突发事件，做好业务连续性保障；负责团队管理及人员培养，制定清晰的工作目标及方向，结果导向；其他上级交办的事务。
