INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (954, N'行政经理（上海）', 1, N'学历不限', N'社招', N'SEC   ', N'1、负责楼宇内行政全模块运营管理，做好员工各项服务，办公区空间、环境的品质管理，含装修验收、搬迁、入住前期筹备及日常运营（如前台、保洁、绿植、设施、康体中心等），持续提升工作环境及服务体验；对设施相关系统运营管理有基本了解，如暖通、电气、电梯、给排水、照明、基础小规模改造等； 2、负责楼宇全品类供应商管理及考核、合规化建设；贯彻行政部制度规范及SOP并在日常运营中结合实际反馈并提出优化建议； 3、负责楼宇行政费用管控及运营数据分析，制定可执行的管控策略，推动降本增效；配合业务完成各类活动、项目等需求落地，根据需求给出高质量方案并完成交付； 4、沟通协调跨部门资源、妥善应对各类突发事件，做好业务连续性保障； 5、负责团队管理及人员培养，制定清晰的工作目标及方向，结果导向；其他上级交办的事务。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (955, N'行政政策与产品专家', 1, N'学历不限', N'社招', N'SEC   ', N'1、政策研究与制定：围绕业务需求，研究和分析相关政策、法规，识别问题与机会，提出可行方案，参与制定基于数据和证据的政策、指引和举措，支持业务发展、创新和客户体验提升； 2、战略规划：支持区域团队搭建与政策举措匹配的战略规划和框架，并设定可衡量的成果指标； 3、业务协作与咨询支持：与业务团队密切协作，洞察需求，共创系统性、可落地的解决方案，为运营团队及业务负责人提供专业建议，运用行业经验输出解决方案； 4、产品系统优化与数据管理：与产品/研发团队紧密协作，围绕行政及企业服务相关系统，负责需求梳理、方案设计、产品规划与迭代跟进，推动系统化、产品化落地，通过数据分析和前后对比模型评估政策和项目成效，建立持续监测与评估机制，搭建COE活动的关键指标体系，跟踪进展并输出管理报告，为决策提供依据； 5、项目管理与变更推动：负责相关项目的整体规划、执行与复盘，确保按时高质量交付，牵头推动变革与转型项目，提供必要的培训与支持，保障平稳落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (956, N'行政政策与产品专家', 1, N'学历不限', N'社招', N'SEC   ', N'1、政策研究与制定：围绕业务需求，研究和分析相关政策、法规，识别问题与机会，提出可行方案，参与制定基于数据和证据的政策、指引和举措，支持业务发展、创新和客户体验提升； 2、战略规划：支持区域团队搭建与政策举措匹配的战略规划和框架，并设定可衡量的成果指标； 3、业务协作与咨询支持：与业务团队密切协作，洞察需求，共创系统性、可落地的解决方案，为运营团队及业务负责人提供专业建议，运用行业经验输出解决方案； 4、产品系统优化与数据管理：与产品/研发团队紧密协作，围绕行政及企业服务相关系统，负责需求梳理、方案设计、产品规划与迭代跟进，推动系统化、产品化落地，通过数据分析和前后对比模型评估政策和项目成效，建立持续监测与评估机制，搭建COE活动的关键指标体系，跟踪进展并输出管理报告，为决策提供依据； 5、项目管理与变更推动：负责相关项目的整体规划、执行与复盘，确保按时高质量交付，牵头推动变革与转型项目，提供必要的培训与支持，保障平稳落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (957, N'行政系统规划与智能化产品经理-Administration Control and Analytics', 1, N'学历不限', N'社招', N'ECI   ', N'1、负责梳理行政端到端业务流程、用户场景、系统边界和关键数据对象，制定中长期行政系统及行政智能化规划、需求分析、方案设计、落地实施及全生命周期管理； 2、深入理解全球行政业务目标及运营模式，以及行政与供应商及各业务团队之间的协作关系，识别高价值场景，推动大模型、AI Agent、知识库、工作流等能力在员工服务、餐饮、办公空间、资产及运营供应商管理等核心场景的智能化落地； 3、建立行政系统与智能化的指标体系和评估机制，围绕用户体验、流程效率、运营质量、智能化水平和成本效益持续跟踪效果，通过数据分析和用户反馈驱动迭代； 4、与系统团队、房产、物理安全、采购及各业务团队紧密协作，打通系统间壁垒，提高整体协作效率，并探索和建设可复用、可拓展的行政能力，支持全球不同业务场景； 5、持续关注企业服务、智能办公、IoT、空间科技和数字化运营的发展趋势，结合行业最佳实践与公司实际需求，形成前瞻性规划并推动验证和落地。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (958, N'行政设施经理', 1, N'学历不限', N'社招', N'SEC   ', N'1、统筹负责片区职场设施设备的整体运行管理与战略规划，制定并持续完善区域设施管理标准与制度体系，保障设施设备高效、稳定、合规运行； 2、主导餐饮空间专用设备及展厅等专用/特殊空间的设施设备管理，构建标准化运维流程，提升专业空间的运营保障水平； 3、统筹职场改造项目的整体管理，对改造方案、工程量及施工质量进行审核把控，并推动项目全周期风险管控与成本优化； 4、建立并优化供应商预防性维修保养管理机制，统筹计划制定与执行落地，全面掌控设施设备运行状况，完善监督与考核体系； 5、牵头区域设施专项及疑难问题攻坚，主导设备设施管理优化与效率提升，输出可复制的管理经验与解决方案，持续提升设施管理的整体稳定性与专业化水平。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (959, N'行政数据治理和数据分析-Administration Control and Analytics', 1, N'学历不限', N'社招', N'IEC   ', N'1、参与行政数据基础信息层、资源组合层、运营过程层、成本层的建设与落地，协助完成核心数据对象梳理、字段定义与口径对齐； 2、负责对接各业务线（餐饮、楼宇运营、员工服务）及数据团队，推动职场主数据、空间字典、财务参考表等基础表的接入与维护，开展日常数据提取、清洗与校验，维护数据字典与口径文档，保障数据一致性； 3、协助搭建行政指标体系，定义指标口径、计算逻辑与更新频率，确保跨区域、跨品类数据可比； 4、参与风险预警与归因分析，对预算偏差、KPI异常、供应商质量波动等问题进行数据追踪与原因定位，围绕成本、服务质量、运营效率等维度，开展跨品类、跨区域的常态化数据分析，输出分析报告与洞察； 5、支持管理层决策会议的数据需求，提供数据支撑与横向对比分析，对接业务团队的数据需求，提供专项分析支持，推动数据结论落地为运营改进动作； 6、探索并实践AI工具（大模型、AI Agent、自动化工作流等）在数据处理、报表生成、智能问答等场景中的应用，提升团队数据运营效率。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (960, N'部门助理', 1, N'学历不限', N'社招', N'SEC   ', N'1、策划组织部门活动，包括但不限于管理研讨会、全员面对面和员工文化活动等大小型活动； 2、负责部门日常行政事务及工位规划管理，包括但不限于费用管理、宣传表彰、礼品定制、制度传达等日常行政事务，以及根据业务需求协调工位资源、合理规划工位以满足业务发展； 3、负责内外部沟通与关系协调，把控业务需求，整合多方资源，协同推进跨部门复杂项目顺利落地； 4、参与优化完善助理体系整体的管理目标、工作流程，推进各项工作的标准化，结合实际工作提出创新性改进建议； 5、完成业务方交办的其他临时性工作与项目型工作。
INSERT INTO [dbo].[jobs] ([job_id], [job_title], [industry_id], [education_requirement], [job_type], [holland_code], [job_description], [company_id], [salary_range], [city], [salary_min_k], [salary_max_k], [crawl_date], [major_names], [salary_ref_min_k], [salary_ref_max_k], [salary_ref_basis]) VALUES (961, N'部门助理', 1, N'学历不限', N'社招', N'SEC   ', N'1、策划组织部门活动：包括但不限于管理研讨会、全员面对面和员工文化活动等大中小型活动； 2、负责部门日常行政事务：包括但不限于费用管理、宣传表彰、礼品定制和制度传达等； 3、负责部门工位规划与管理：根据业务需求，协调工位资源，合理规划工位，满足业务发展； 4、负责内外部沟通与关系协调：把控业务需求，整合多方资源，协同推进跨部门复杂项目顺利落地； 5、参与优化完善助理体系整体的管理目标、工作流程，推进各项工作的标准化，结合实际工作提出创新性改进建议； 6、完成业务方交办的其他临时性工作与项目型工作。 1 2 3 联系我们? 相关网站? 候选人反馈平台 官网使用体验反馈 字节跳动 校园招聘 全球招聘 字节跳动 Seed ?? Hi，有什么可以帮你？ 我可以推荐岗位、查询投递进度、解答招聘相关问题。想从哪个开始？ 你的 AI 求职搭子来了 政策流程不了解、岗位不知道怎么选， 一个入口全搞定 线上咨询 政策、流程随时问，回答迅速又靠谱 个性化荐岗 上传简历、表达意向，秒懂并推荐你适合的岗位 稍后再说 立即体验
