INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (2, N'Python', N'编程语言', N'通用脚本语言，用于数据分析、机器学习、后端服务、自动化运维。生态含 NumPy/Pandas/Scikit-learn/Django/FastAPI。可评级：1=掌握语法与数据结构 2=能写脚本处理日常任务 3=能用库完成数据分析或接口开发 4=能优化性能与工程化 5=能设计算法方案与工程架构。', NULL, NULL, N'软件工程|计算机科学与技术|物理学|应用物理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (3, N'Go', N'编程语言', N'静态编译语言，以高并发和部署简单见长，用于云原生基础设施、微服务、区块链后端。可评级：1=掌握语法与 goroutine 概念 2=能写基础服务 3=能用 Gin/gRPC 开发微服务 4=能做并发与内存优化 5=能设计高并发系统。', NULL, 23, N'软件工程|计算机科学与技术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (4, N'C++', N'编程语言', N'系统级编程语言，用于游戏引擎、嵌入式、高性能计算、金融交易系统。可评级：1=掌握语法与指针概念 2=能写结构化程序 3=能使用 STL 与类设计 4=能做内存与性能优化 5=能设计跨平台高性能架构。', NULL, NULL, N'软件工程|计算机科学与技术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (5, N'C#', N'编程语言', N'微软生态主力语言，用于 .NET 后端服务、Unity 游戏开发、桌面应用。可评级：1=掌握语法与面向对象 2=能写控制台或简单窗体程序 3=能用 ASP.NET 开发接口 4=能使用异步与依赖注入 5=能设计企业级应用架构。', NULL, 23, N'软件工程|计算机科学与技术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (6, N'PHP', N'编程语言', N'Web 后端脚本语言，用于中小型网站与内容管理系统。可评级：1=掌握语法 2=能写页面逻辑 3=能用框架（Laravel/ThinkPHP）开发模块 4=能做性能与安全优化 5=能设计高并发 Web 架构。', NULL, 23, N'软件工程|计算机科学与技术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (7, N'SQL', N'编程语言', N'关系型数据库查询与操作语言，用于数据提取、报表、数据清洗、业务查询。可评级：1=会写 SELECT 与条件过滤 2=能做多表 JOIN 与聚合 3=能写子查询与窗口函数 4=能做执行计划与索引优化 5=能设计数据模型与复杂分析查询。', NULL, NULL, N'大数据管理与应用|统计学|信息与计算科学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (8, N'MySQL', N'技术框架与平台', N'开源关系型数据库，用于业务数据持久化。含索引设计、事务隔离、主从复制、分库分表。可评级：1=会建库建表与增删改查 2=能写复杂查询 3=能做索引与慢查询优化 4=能设计分库分表与主从架构 5=能规划高可用与容灾方案。', NULL, NULL, N'软件工程|计算机科学与技术');
