INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (10, N'MongoDB', N'技术框架与平台', N'文档型 NoSQL 数据库，用于半结构化数据存储与快速迭代场景。可评级：1=会增删改查 2=能设计文档模型 3=能做聚合查询与索引优化 4=能规划分片集群 5=能设计大规模数据存储方案。', NULL, NULL, N'软件工程|计算机科学与技术');
