INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (13, N'微服务', N'技术框架与平台', N'将单体系统拆分为独立可部署服务的架构方法。含服务注册发现、网关、配置中心、链路追踪、熔断限流。可评级：1=理解微服务与单体差异 2=能开发单个服务 3=能完成服务间调用与注册发现 4=能做熔断降级与链路追踪 5=能设计服务拆分边界与治理规范。', N'Microservices', 23, N'软件工程|计算机科学与技术');
