INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (36, N'SPSS', N'软件工具', N'统计分析软件，用于问卷数据、社科与心理研究中的统计检验。可评级：1=会数据录入与描述统计 2=能做 t 检验与方差分析 3=能做回归与相关分析 4=能做因子分析与信效度检验 5=能独立设计分析方案并解读结果。', NULL, NULL, N'统计学|心理学|应用心理学|教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (39, N'Axure', N'软件工具', N'交互原型设计工具，用于产出可点击的中保真原型与需求说明。可评级：1=会画静态线框 2=能做页面跳转原型 3=能做动态交互与条件逻辑 4=能输出规范标注与文档 5=能独立完成完整产品原型方案。', NULL, NULL, N'软件工程|数字媒体技术|数字媒体艺术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (40, N'Figma', N'软件工具', N'在线协作设计工具，用于 UI 设计、组件库、设计交付与多人协作。可评级：1=会画基础界面 2=能用组件与样式 3=能做自动布局与响应式设计 4=能建组件库与设计规范 5=能主导设计系统与跨团队协作流程。', NULL, NULL, N'软件工程|数字媒体技术|数字媒体艺术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (41, N'Sketch', N'软件工具', N'macOS 端 UI 设计工具，用于界面设计与设计稿交付。可评级：1=会画基础界面 2=能用符号（Symbols）复用 3=能管理图层与切图导出 4=能建组件库 5=能主导设计规范与协作流程。', NULL, NULL, N'软件工程|数字媒体技术|数字媒体艺术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (42, N'Photoshop', N'软件工具', N'位图图像处理软件，用于图片精修、合成、海报与界面视觉素材制作。可评级：1=会基础工具与图层 2=能做抠图与调色 3=能做合成与海报设计 4=能精修人像与商品图 5=能制定视觉规范与批量处理流程。', N'PS|Adobe Photoshop', NULL, N'教育学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (44, N'原型', N'分析与设计方法', N'用线框或可交互稿表达产品结构与流程的能力。含信息架构、页面流程、低保真/中保真原型。可评级：1=会画单页线框 2=能画出完整流程 3=能做可点击交互原型 4=能输出规范标注与需求文档 5=能主导复杂系统的原型方案。', NULL, NULL, N'软件工程|数字媒体技术|数字媒体艺术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (45, N'交互设计', N'分析与设计方法', N'设计人与系统的操作流程与反馈机制。含任务分析、流程设计、状态与异常处理、可用性测试。可评级：1=了解交互原则 2=能设计单页面操作流程 3=能处理完整业务链路的交互 4=能做可用性测试并迭代 5=能建立交互规范与设计系统。', N'Interaction Design', NULL, N'软件工程|数字媒体技术|数字媒体艺术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (46, N'视觉设计', N'分析与设计方法', N'通过版式、色彩、图形传达信息与品牌调性的能力。含栅格与层级、配色、字体、图标与插画、品牌延展。可评级：1=会基础排版与配色 2=能做单页视觉稿 3=能做完整界面视觉方案 4=能建立视觉规范与组件 5=能主导品牌视觉体系。', NULL, NULL, N'软件工程|数字媒体技术|数字媒体艺术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (47, N'UI', N'分析与设计方法', N'用户界面设计，关注布局、控件、状态与设计规范，产出可交付的设计稿与标注。可评级：1=会使用设计工具画界面 2=能做规范排版与控件使用 3=能独立完成多页面界面设计 4=能做设计规范与组件库 5=能主导设计系统与跨端一致性。', NULL, NULL, N'软件工程|数字媒体技术|数字媒体艺术');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (50, N'财务分析', N'分析与设计方法', N'通过报表与指标判断企业经营状况。含三大报表解读、比率分析、趋势与同业对比、经营诊断。可评级：1=能看懂报表科目 2=会算常用财务比率 3=能做趋势与结构分析 4=能结合业务做归因诊断 5=能输出决策建议与预警机制。', NULL, NULL, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (53, N'档案管理', N'文献与信息处理', N'对档案的收集、整理、保管、利用进行全流程管理的能力。含归档范围、保管期限、库房管理、借阅与保密。可评级：1=了解档案类型与制度 2=能完成收集与归档 3=能独立做整理与编目 4=能设计管理制度与分类方案 5=能主导数字化与档案体系建设。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (54, N'档案数字化', N'文献与信息处理', N'将纸质档案转化为数字影像并建立可检索数据库的能力。含扫描参数、图像处理、著录挂接、质检与备份。可评级：1=了解数字化流程 2=能按规范扫描 3=能做图像处理与挂接 4=能设计质检与验收标准 5=能主导数字化项目。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (57, N'心理测评', N'评估与干预方法', N'使用标准化量表评估个体心理特质与状态的方法。含量表选择、施测规范、计分解释、报告撰写与伦理边界。可评级：1=了解测评用途与伦理 2=能按规范施测 3=能独立计分与初步解释 4=能组合量表做综合评估 5=能设计方案并撰写专业报告。', N'心理测量', NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (58, N'团体辅导', N'评估与干预方法', N'以小组形式开展心理干预的方法。含团体动力、活动设计、阶段推进、成员筛选与风险处理。可评级：1=了解团体阶段与规则 2=能协助带领活动 3=能设计单次团辅方案 4=能独立带领完整团体 5=能设计方案并做效果评估。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (59, N'危机干预', N'评估与干预方法', N'对自杀、自伤、重大创伤等紧急状态的识别与处置能力。含风险评估、安全计划、转介流程、家属沟通。可评级：1=了解危机信号与转介渠道 2=能做初步风险筛查 3=能执行安全计划与稳定化技术 4=能主导个案处置与多方联动 5=能建立危机干预流程与培训体系。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (60, N'心理咨询', N'评估与干预方法', N'通过谈话关系帮助来访者解决心理困扰的专业能力。含建立关系、评估、个案概念化、干预技术、结束与随访。可评级：1=了解咨询流程与伦理 2=能建立关系与基础倾听回应 3=能完成个案概念化并持续咨询 4=能处理阻抗与复杂议题 5=能独立执业并接受督导。', N'个体咨询', NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (61, N'课程设计', N'教学与训练方法', N'根据教学目标与学情组织内容、活动与评价的整体设计能力。含目标分解、内容序列、活动设计、评价方案。可评级：1=能写单课时教案 2=能设计单元教学 3=能做完整课程大纲与评价方案 4=能做课程迭代与学情适配 5=能主导课程体系与校本课程开发。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (62, N'教案', N'教学与训练方法', N'单节课的教学设计文档，含教学目标、重难点、过程、板书与作业。可评级：1=了解教案结构 2=能按模板写完整教案 3=能设计有层次的提问与活动 4=能针对不同学情调整设计 5=能输出示范教案并指导教师。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (75, N'需求分析', N'组织与管理', N'识别并定义真实需求的能力。含用户访谈、场景分析、需求优先级、需求文档、变更管理。可评级：1=能记录与整理需求 2=能做用户访谈并归纳痛点 3=能写需求文档与流程图 4=能做优先级排序与方案权衡 5=能主导需求体系与跨部门对齐。', N'Requirements Analysis', NULL, N'软件工程|信息资源管理|大数据管理与应用');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (76, N'用户研究', N'组织与管理', N'用定性与定量方法理解用户行为与需求的能力。含访谈、问卷、可用性测试、竞品分析、用户画像。可评级：1=了解研究方法 2=能执行访谈与问卷 3=能独立完成一次研究并出报告 4=能设计混合方法研究 5=能主导研究体系并推动决策落地。', N'User Research', NULL, N'软件工程|信息资源管理|大数据管理与应用');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (77, N'项目管理', N'组织与管理', N'在约束条件下推动目标达成的能力。含范围、进度、成本、质量、风险、沟通管理。可评级：1=了解项目管理要素 2=能跟踪任务与进度 3=能独立管理小型项目 4=能做风险与干系人管理 5=能主导复杂项目群与流程改进。', N'Project Management', NULL, N'软件工程|信息资源管理|大数据管理与应用');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (78, N'文案', N'表达与内容创作', N'为产品或活动撰写有说服力的文字。含卖点提炼、标题写作、详情页、广告语、转化引导。可评级：1=能写通顺的产品介绍 2=能提炼卖点并写标题 3=能独立完成详情页或推文 4=能针对不同渠道调整语气与结构 5=能建立文案规范并做 A/B 优化。', NULL, NULL, N'教育学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (87, N'成本核算', N'分析与设计方法', N'归集与分配生产或服务成本的方法。含品种法/分批法/分步法、制造费用分配、成本还原。可评级：1=理解成本构成 2=能归集直接材料与人工 3=能完成制造费用分配与产品成本计算 4=能做成本差异分析 5=能设计成本核算体系与降本方案。', NULL, NULL, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (90, N'纳税申报', N'分析与设计方法', N'按税法规定完成各税种申报与缴纳的实操能力。含增值税、企业所得税、个税、附加税及申报表填写。可评级：1=了解主要税种 2=能填写基础申报表 3=能独立完成月度/季度申报 4=能做税会差异调整与汇算清缴 5=能做税务筹划与风险管控。', NULL, NULL, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (94, N'用友', N'软件工具', N'国产财务与企业管理软件，用于账务处理、报表、供应链与人力管理。可评级：1=了解模块结构 2=能做凭证录入与查询 3=能完成月度结账与报表出具 4=能做参数配置与流程设置 5=能主导系统实施与数据迁移。', NULL, 97, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (95, N'金蝶', N'软件工具', N'国产财务与企业管理软件（KIS/K3/云星空），用途与用友相近。可评级：1=了解模块结构 2=能做凭证与单据录入 3=能完成结账与报表 4=能做系统配置与流程 5=能主导实施与业财一体化方案。', NULL, 97, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (96, N'SAP', N'软件工具', N'国际主流 ERP 系统，覆盖财务（FI/CO）、供应链（MM/SD）、生产（PP）等模块。可评级：1=熟悉界面与主数据概念 2=能在指定模块做单据操作 3=能独立处理模块内业务流程 4=能做配置与权限设计 5=能主导模块实施与跨模块集成。', NULL, 97, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (97, N'财务软件', N'软件工具', N'技能族：财务核算与管理软件的使用能力，下含用友、金蝶、SAP 及各类云财务工具。可评级：1=了解模块划分 2=能做凭证录入 3=能完成结账出报表 4=能做配置与流程优化 5=能主导实施与系统集成。', NULL, NULL, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (99, N'资金管理', N'分析与设计方法', N'企业现金流的计划、调度与风险控制。含资金计划、收支管理、融资安排、外汇与流动性管理。可评级：1=了解资金岗位职责 2=能编制资金日报 3=能编制资金计划并跟踪执行 4=能做融资方案与成本测算 5=能设计集团资金池与风险管控体系。', NULL, NULL, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (100, N'审计底稿', N'分析与设计方法', N'审计过程中记录证据与结论的规范化工作。含审计程序表、抽凭记录、函证、调整分录、底稿归档。可评级：1=了解底稿结构与规范 2=能按模板填写程序表 3=能独立完成科目底稿 4=能设计审计程序并判断重要性 5=能复核底稿与把控项目质量。', NULL, NULL, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (102, N'预算管理', N'分析与设计方法', N'编制、执行与考核企业预算的闭环方法。含经营预算、资本预算、滚动预测、差异分析。可评级：1=了解预算体系 2=能编制部门费用预算 3=能完成全面预算编制 4=能做执行差异分析与滚动预测 5=能设计预算管控与考核机制。', NULL, NULL, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (103, N'财务建模', N'分析与设计方法', N'用表格工具搭建财务预测与估值模型。含假设驱动、三表联动、DCF、敏感性分析。可评级：1=能搭建简单收支预测 2=能做三表联动 3=能搭建 DCF 估值模型 4=能做情景与敏感性分析 5=能独立完成投资并购级建模。', NULL, NULL, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (108, N'合并报表', N'分析与设计方法', N'将母子公司报表抵销合并的编制能力。含合并范围判断、内部交易抵销、少数股东权益、商誉处理。可评级：1=了解合并原理 2=能收集与校验子公司报表 3=能完成常规抵销分录 4=能处理复杂股权与内部交易 5=能主导集团合并与披露。', NULL, NULL, N'会计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (113, N'课堂管理', N'教学与训练方法', N'维持课堂秩序与学习氛围的组织能力。含规则建立、节奏控制、提问互动、突发处理。可评级：1=了解管理基本原则 2=能维持基本课堂秩序 3=能调动学生参与 4=能处理冲突与个别学生问题 5=能建立班级管理机制。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (115, N'家校沟通', N'教学与训练方法', N'与学生家长进行有效沟通与协同的能力。含沟通时机、话术、问题反馈、家长会组织。可评级：1=了解沟通原则 2=能完成日常通知与反馈 3=能做个别学生情况沟通 4=能处理家长异议与敏感问题 5=能建立家校协同机制。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (116, N'教研', N'教学与训练方法', N'围绕教学问题开展研究并改进教学的能力。含问题聚焦、集体备课、课例研究、数据分析和成果提炼。可评级：1=能参与教研活动 2=能做课例记录与反思 3=能独立设计小课题 4=能带领教研组开展研究 5=能形成可推广的教学成果。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (117, N'听课评课', N'教学与训练方法', N'观察课堂并给出结构化反馈的能力。含观察量表、记录方法、评课框架、改进建议。可评级：1=了解评课维度 2=能完整记录一节课 3=能按维度给出具体反馈 4=能诊断教学问题并提改进方案 5=能设计评课标准并指导教师成长。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (118, N'课件制作', N'教学与训练方法', N'制作支撑教学的演示与多媒体材料。含内容结构化、版式设计、图示化、动画与互动。可评级：1=会套模板做课件 2=能做到清晰排版 3=能把知识点图示化 4=能设计互动与动画节奏 5=能形成课程视觉与资源体系。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (119, N'教学评估', N'教学与训练方法', N'对学生学习效果与教学质量的测量与判断。含命题设计、信效度、过程性评价、数据分析与反馈。可评级：1=了解评估类型 2=能编制基础测验 3=能分析成绩并做讲评 4=能设计过程性与多元评价方案 5=能建立课程评估体系并用于改进。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (120, N'学情分析', N'教学与训练方法', N'基于学生数据判断学习基础与困难的能力。含前测、作业与错题分析、分层画像、教学调整。可评级：1=能收集学生基础信息 2=能做前测与成绩统计 3=能分析错题与薄弱点 4=能做分层画像并调整教学 5=能建立学情跟踪机制。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (121, N'因材施教', N'教学与训练方法', N'根据学生差异调整教学目标、内容与支持方式的能力。含分层目标、差异化任务、个别辅导。可评级：1=了解差异表现 2=能设计分层任务 3=能针对不同层次调整教学 4=能制定个别化支持方案 5=能建立分层教学体系。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (122, N'双语教学', N'教学与训练方法', N'用中英双语组织学科教学的能力。含学科英语表达、双语切换节奏、术语对照、学生语言支持。可评级：1=能用英语讲解基本概念 2=能双语组织一节课 3=能设计双语教学材料 4=能平衡学科深度与语言难度 5=能主导双语课程建设。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (123, N'蒙台梭利', N'教学与训练方法', N'以儿童自主操作教具为核心的教育法。含有准备的环境、教具操作、观察记录、混龄教学。可评级：1=了解核心理念与教具 2=能规范操作日常区教具 3=能带班并做观察记录 4=能设计有准备的环境 5=能主导蒙氏班级与教师培训。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (124, N'奥尔夫', N'教学与训练方法', N'以节奏、律动、即兴为核心的的音乐教育法。含声势、打击乐、乐器合奏、即兴创编。可评级：1=了解奥尔夫理念 2=能做基础节奏与声势活动 3=能组织乐器合奏 4=能设计完整课例 5=能主导奥尔夫课程与师资培训。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (125, N'感统训练', N'教学与训练方法', N'针对感觉统合失调儿童的训练方法。含前庭、本体、触觉训练器材使用与方案设计。可评级：1=了解感统失调表现 2=能安全使用基础器材 3=能按评估结果做单项训练 4=能设计个别化训练方案 5=能主导训练课程并做效果评估。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (130, N'少儿英语', N'教学与训练方法', N'面向儿童开展英语教学的能力。含自然拼读、TPR 教学法、游戏与绘本、课堂激励。可评级：1=能组织简单英语活动 2=能教自然拼读基础 3=能设计完整课时 4=能针对不同年龄调整方法 5=能主导课程体系与教研。', NULL, NULL, N'教育学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (133, N'SCL-90', N'评估与干预方法', N'症状自评量表（90 项），用于筛查躯体化、强迫、抑郁、焦虑等九类症状的严重程度。可评级：1=了解量表维度与计分 2=能规范施测 3=能计分并识别阳性因子 4=能结合访谈做初步判断 5=能撰写解释报告并给出转介建议。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (134, N'MMPI', N'评估与干预方法', N'明尼苏达多项人格测验，用于人格特征与心理病理的临床评估。可评级：1=了解量表结构与效度量表 2=能规范施测 3=能读懂剖面图与关键量表 4=能结合临床访谈做整合解释 5=能独立用于临床或人事评估并撰写报告。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (135, N'16PF', N'评估与干预方法', N'卡特尔 16 种人格因素问卷，用于人格特质描述。可评级：1=了解 16 因素含义 2=能规范施测 3=能计分并解释主要因素 4=能结合应用场景（选拔/咨询）做整合分析 5=能撰写人格评估报告。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (136, N'EPQ', N'评估与干预方法', N'艾森克人格问卷，测量内外向、神经质、精神质与掩饰性。可评级：1=了解四维度含义 2=能规范施测 3=能计分并解释维度得分 4=能结合常模做对比分析 5=能用于研究与实际评估并撰写报告。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (137, N'认知行为疗法', N'评估与干预方法', N'通过识别与修正非理性认知来改善情绪行为的结构化疗法（CBT）。含认知概念化、自动思维记录、行为实验、暴露与家庭作业。可评级：1=了解 ABC 模型 2=能识别自动思维 3=能完成结构化个案概念化 4=能灵活运用行为技术与处理阻抗 5=能独立开展完整 CBT 疗程。', N'CBT', NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (139, N'沙盘游戏', N'评估与干预方法', N'借助沙具与沙盘表达潜意识的分析心理学干预方法。含自由与保护空间、象征理解、阶段推进。可评级：1=了解沙盘设置与规则 2=能陪伴与记录沙盘过程 3=能识别常见象征主题 4=能结合个案做阶段性解读 5=能独立开展完整沙盘治疗。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (140, N'绘画治疗', N'评估与干预方法', N'通过绘画创作表达情绪与冲突的艺术治疗方法。含涂鸦、房树人、曼陀罗等形式。可评级：1=了解绘画治疗的适用与边界 2=能组织基础绘画活动 3=能观察与记录画面特征 4=能结合个案做解读与干预 5=能设计完整治疗方案。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (141, N'音乐治疗', N'评估与干预方法', N'运用音乐体验与音乐活动改善身心状态的方法。含接受式、即兴式、再创造式。可评级：1=了解音乐治疗形式 2=能组织基础音乐活动 3=能根据目标选择曲目与活动 4=能带领个体或团体治疗 5=能设计方案并做效果评估。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (143, N'家庭治疗', N'评估与干预方法', N'以家庭系统为干预单位的治疗方法。含系统视角、家谱图、循环提问、家庭作业。可评级：1=了解系统式思路 2=能绘制家谱图 3=能用循环提问探索互动模式 4=能处理家庭冲突与三角化 5=能独立开展家庭治疗。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (144, N'心理筛查', N'评估与干预方法', N'用简短工具在大规模人群中识别高风险个体的能力。含量表选型、施测组织、风险分级、转介闭环。可评级：1=了解筛查目的与工具 2=能组织施测与回收 3=能按阈值分级并出名单 4=能设计复筛与转介流程 5=能建立全校/全员筛查机制。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (145, N'心理健康教育', N'评估与干预方法', N'面向学生或员工开展心理健康知识普及与能力培养。含课程设计、主题讲座、活动策划、危机预防宣传。可评级：1=了解常见主题 2=能讲一节心理健康课 3=能设计系列课程或活动 4=能针对群体特点设计方案 5=能构建心理健康教育体系。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (146, N'朋辈辅导', N'评估与干预方法', N'培训同龄人提供倾听与支持的服务模式。含选拔、培训、边界与转介、督导。可评级：1=了解朋辈辅导定位与边界 2=能倾听与回应 3=能识别风险并转介 4=能组织朋辈活动 5=能设计并管理朋辈辅导体系。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (150, N'催眠', N'评估与干预方法', N'通过暗示引导进入专注放松状态以开展治疗的技术。含导入、深化、暗示、唤醒与伦理规范。可评级：1=了解催眠原理与适用边界 2=能做基础放松导入 3=能在督导下完成简单催眠流程 4=能结合个案运用催眠干预 5=能独立开展催眠治疗。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (151, N'正念', N'评估与干预方法', N'通过有意识地觉察当下而不评判来调节身心的练习。含呼吸觉察、身体扫描、正念行走、MBSR/MBCT 课程结构。可评级：1=了解正念基本态度 2=能完成基础呼吸与身体扫描 3=能带领短时正念练习 4=能设计 8 周课程 5=能针对特定人群设计方案并评估效果。', NULL, NULL, N'心理学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (152, N'图书分类', N'文献与信息处理', N'依据分类法给文献归类并给出分类号的能力。含学科体系理解、类目判断、交叉学科处理。可评级：1=了解分类法结构 2=能按类目表给常见图书归类 3=能处理交叉与边缘学科 4=能做分类标引审核 5=能参与分类法应用规则制定。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (153, N'中图法', N'文献与信息处理', N'《中国图书馆分类法》的使用能力，含 22 大类体系、复分表、类目组配规则。可评级：1=了解大类框架 2=能查类目表并给出简号 3=能使用复分表组号 4=能处理复杂主题标引 5=能承担标引审核与培训。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (154, N'CNMARC', N'文献与信息处理', N'中国机读目录格式，用于书目数据的标准化著录与交换。含字段定义、指示符、子字段、著录规则。可评级：1=了解记录结构 2=能填写常用字段 3=能独立完成完整书目记录 4=能处理多卷书与特殊文献 5=能审核数据质量与做格式转换。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (155, N'编目', N'文献与信息处理', N'对文献进行描述与主题标引，形成可检索书目记录的能力。含著录规则、分类标引、主题词标引、规范控制。可评级：1=了解编目流程 2=能做简单图书著录 3=能独立完成分类与主题标引 4=能处理多语种与特殊文献 5=能制定编目细则与质量控制。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (156, N'文献检索', N'文献与信息处理', N'按需求制定检索策略并获取文献的能力。含数据库选择、检索式构建、布尔逻辑、查全查准权衡。可评级：1=会用数据库基础检索 2=能构建合理检索式 3=能完成专题检索与筛选 4=能做检索策略优化与综述检索 5=能提供检索咨询与培训。', NULL, NULL, N'档案学|信息资源管理|物理学|应用物理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (157, N'参考咨询', N'文献与信息处理', N'解答用户信息需求并提供深度信息服务的能力。含需求澄清、检索执行、答案组织、信息素养培训。可评级：1=能回答常见咨询 2=能完成事实型检索 3=能做专题咨询并出具报告 4=能开展学科服务 5=能设计咨询服务体系。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (158, N'阅读推广', N'文献与信息处理', N'策划并组织阅读活动以提升阅读参与度。含活动策划、书目推荐、社群运营、效果评估。可评级：1=能组织基础读书活动 2=能编制推荐书目 3=能策划系列活动 4=能设计品牌阅读项目 5=能构建阅读推广体系并评估成效。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (159, N'馆藏管理', N'文献与信息处理', N'对馆藏资源的配置、清点、剔除与布局进行管理。含采购建议、典藏分配、盘点、剔旧。可评级：1=了解馆藏流程 2=能做上架与排架 3=能完成盘点与数据核对 4=能做馆藏结构分析 5=能制定馆藏发展政策。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (162, N'信息组织', N'文献与信息处理', N'对信息资源进行描述、标引与结构化组织的能力。含元数据、分类主题、知识组织体系。可评级：1=了解组织方法 2=能按规则描述资源 3=能建立小型资源体系 4=能设计元数据方案 5=能主导知识组织系统建设。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (163, N'知识管理', N'文献与信息处理', N'对组织知识进行捕获、沉淀、共享与应用的能力。含知识库建设、经验萃取、社区运营、激励机制。可评级：1=了解知识管理概念 2=能整理与归档资料 3=能搭建知识库结构 4=能设计知识运营机制 5=能主导组织知识体系建设。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (164, N'竞争情报', N'文献与信息处理', N'系统收集与分析竞争环境信息支撑决策的能力。含信息源建设、监测体系、分析方法（SWOT/对标/专利分析）、报告输出。可评级：1=了解情报流程 2=能收集整理公开信息 3=能做单项专题分析 4=能建立监测机制并定期报告 5=能主导情报体系与决策支持。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (165, N'信息分析', N'文献与信息处理', N'对信息进行筛选、比较、归纳并形成判断的能力。含信息甄别、定量分析、趋势判断、报告撰写。可评级：1=能整理与归类信息 2=能做对比与归纳 3=能输出结构化的分析结论 4=能结合数据做趋势判断 5=能主导专题研究与决策建议。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (166, N'档案整理', N'文献与信息处理', N'按标准对档案进行区分全宗、分类、组卷、排列与编号的实操能力。含立卷规范、卷内文件排序、案卷目录编制。可评级：1=了解整理流程 2=能做文件分类 3=能独立组卷与编目 4=能做质量检查与整改 5=能设计整理方案与标准。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (167, N'档案著录', N'文献与信息处理', N'按标准描述档案内容与形式特征形成条目数据的能力。含着录项目、著录格式、标引规则。可评级：1=了解著录项目 2=能填写基础著录条目 3=能独立完成案卷级著录 4=能处理特殊载体档案 5=能审核数据并制定著录细则。', NULL, NULL, N'档案学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (170, N'Office', N'软件工具', N'技能族：办公套件综合使用能力，下含 Word、Excel、PPT 及协作工具。可评级：1=会基本录入与排版 2=能独立完成日常文档表格 3=能做规范报告与汇报材料 4=能做数据联动与模板化 5=能制定团队文档规范与自动化流程。', N'WPS|办公软件', NULL, N'会计学|档案学|教育学|信息资源管理|统计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (171, N'Word', N'软件工具', N'文字处理软件，用于公文、报告、论文、合同的撰写与排版。可评级：1=会录入与基础格式 2=会用样式与目录 3=能做长文档排版与页眉页脚 4=能用邮件合并与批注修订协作 5=能制定文档模板与排版规范。', NULL, NULL, N'会计学|档案学|教育学|信息资源管理|统计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (172, N'PPT', N'软件工具', N'演示文稿软件，用于汇报、方案、课程与路演材料制作。可评级：1=会套模板排版 2=能做到图文清晰对齐 3=能用图表与逻辑结构讲清观点 4=能设计统一视觉风格与动画节奏 5=能主导重要汇报的整体策划与呈现。', N'PowerPoint|幻灯片', NULL, N'会计学|档案学|教育学|信息资源管理|统计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (173, N'公文写作', N'表达与内容创作', N'按规范撰写机关与企事业单位公文的能力。含通知、报告、请示、纪要、总结的格式与行文规则。可评级：1=了解公文种类与格式 2=能写通知与简单报告 3=能独立起草请示与总结 4=能处理复杂材料与领导讲话稿 5=能审核把关并制定行文规范。', NULL, NULL, N'会计学|档案学|教育学|信息资源管理|统计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (174, N'新闻稿', N'表达与内容创作', N'撰写新闻通稿与活动报道的能力。含标题、导语、主体结构、引语使用、事实核查。可评级：1=了解新闻结构 2=能写活动简讯 3=能独立完成通稿 4=能提炼新闻点并做深度报道 5=能策划传播方案与媒体对接。', NULL, NULL, N'教育学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (175, N'公众号运营', N'表达与内容创作', N'运营微信公众号的内容与用户。含选题、排版、发布节奏、粉丝互动、数据复盘。可评级：1=会排版与发布 2=能独立完成单篇推文 3=能规划选题与栏目 4=能做用户增长与活动策划 5=能搭建内容矩阵并做商业转化。', NULL, NULL, N'教育学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (176, N'新媒体运营', N'表达与内容创作', N'在社交与内容平台开展账号运营与增长的能力。含平台规则、内容策划、投放、社群、数据复盘。可评级：1=了解平台规则 2=能发布与维护账号 3=能策划内容与活动 4=能做投放与增长实验 5=能制定矩阵策略与商业目标。', NULL, NULL, N'教育学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (177, N'视频剪辑', N'表达与内容创作', N'对视频素材进行剪辑、包装与输出的能力。含镜头组接、节奏、字幕、配乐、调色、导出规范。可评级：1=会剪切与拼接 2=能加字幕与配乐 3=能独立剪出完整短片 4=能做包装与调色 5=能策划与把控成片风格。', NULL, NULL, N'教育学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (178, N'Premiere', N'软件工具', N'视频剪辑软件，用于宣传片、课程视频、短视频的剪辑与包装。可评级：1=会导入导出与剪切 2=能做字幕与转场 3=能做多轨剪辑与调色 4=能做特效包装与音频处理 5=能独立完成成片并把控节奏与风格。', NULL, NULL, N'教育学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (179, N'剪映', N'软件工具', N'轻量视频剪辑工具，用于短视频剪辑、字幕生成、模板套用。可评级：1=会剪切与拼接 2=能加字幕与音乐 3=能用模板与转场做完整短视频 4=能做调色与音效包装 5=能批量产出并保持风格统一。', NULL, NULL, N'教育学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (180, N'活动策划', N'表达与内容创作', N'从目标出发设计并落地活动的能能力。含主题创意、流程设计、预算、物料、执行分工、风险预案、复盘。可评级：1=能执行分配的任务 2=能写活动方案 3=能独立统筹小型活动 4=能管理预算与多方协作 5=能策划大型活动并做效果评估。', NULL, NULL, N'教育学|信息资源管理');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (182, N'社会工作', N'社会工作方法', N'技能族：以助人自助为宗旨的专业服务方法总称，下含个案、小组、社区三大方法及资源链接与政策倡导。可评级：1=了解专业价值观与伦理 2=能开展需求评估 3=能按方法开展服务 4=能设计服务方案并整合资源 5=能主导项目与督导他人。', NULL, NULL, NULL);
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (183, N'个案工作', N'社会工作方法', N'一对一为个人或家庭提供专业服务的方法。含接案、预估、计划、介入、评估、结案流程与专业关系建立。可评级：1=了解个案流程与记录规范 2=能建立专业关系并做基础访谈 3=能完成预估与介入计划 4=能处理复杂个案与危机 5=能独立管理个案并接受督导。', NULL, 182, N'教育学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (184, N'小组工作', N'社会工作方法', N'以小组为载体的社会工作方法。含小组动力、需求评估、活动设计、阶段推进、效果评估。可评级：1=了解小组类型与阶段 2=能协助带领小组 3=能设计单节小组活动 4=能独立带领完整小组 5=能设计方案并做成效评估。', NULL, 182, N'教育学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (185, N'社区工作', N'社会工作方法', N'以社区为单位的社会工作方法。含社区需求评估、资源地图、居民动员、组织培育、项目运营。可评级：1=了解社区工作模式 2=能做社区走访与需求调研 3=能组织社区活动 4=能培育社区组织与志愿者 5=能主导社区项目与治理创新。', NULL, 182, N'教育学|应用心理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (186, N'统计学', N'分析与设计方法', N'运用描述统计与推断统计方法处理数据的技能。含分布描述、假设检验、置信区间、回归分析、贝叶斯推断。可评级：1=了解基本概念 2=能算描述统计 3=能选对检验方法 4=能建模与解释结果 5=能设计分析方案。', N'Statistics', NULL, N'大数据管理与应用|统计学|信息与计算科学|物理学|应用物理学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (187, N'数据可视化', N'分析与设计方法', N'将数据转化为图表并有效传达结论的技能。含图表类型选择、维度与度量设计、仪表盘搭建、可视化叙事。常用 Tableau/Power BI/Excel/Python(matplotlib,seaborn)/R(ggplot2)。可评级：1=认识图表类型 2=能做基础图表 3=能选对图表表达 4=能搭仪表盘 5=能设计可视化叙事。', N'Data Visualization', NULL, N'大数据管理与应用|统计学|信息与计算科学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (188, N'云计算', N'技术框架与平台', N'在云平台上部署与运维应用的技能。含 IaaS/PaaS 概念、虚拟机与容器编排、对象存储、云网络、弹性伸缩、云安全。主流平台 AWS/阿里云/腾讯云/华为云/GCP。可评级：1=了解云概念 2=会用控制台开资源 3=能部署单体应用 4=能设计高可用架构 5=能做成本与安全优化。', N'Cloud Computing', NULL, N'大数据管理与应用|统计学|信息与计算科学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (189, N'大数据', N'技术框架与平台', N'技能族：处理超单机规模数据的技术集合。下含分布式存储与计算（Hadoop/HDFS）、内存计算（Spark）、流处理（Flink/Kafka）、数据仓库（Hive/ClickHouse）、查询引擎（Presto）。可评级：1=了解生态组成 2=会写 SQL 查数仓 3=能开发 Spark 作业 4=能做任务调优 5=能设计数据架构。', N'Big Data', NULL, N'大数据管理与应用|统计学|信息与计算科学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (197, N'数值计算', N'分析与设计方法', N'用数值方法求解无法解析求解的数学问题的能力。含误差分析、插值与拟合、数值积分与微分、线性方程组与特征值、常微分方程数值解、算法稳定性与收敛性。可评级：1=了解误差与浮点概念 2=会调用现成程序求解 3=能独立实现基本数值算法 4=能针对病态问题选择并改进算法 5=能设计算法并分析收敛性。', N'数值分析|计算方法|Numerical Computation', NULL, N'物理学|应用物理学|数学与应用数学|信息与计算科学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (198, N'实验设计', N'分析与设计方法', N'根据研究问题设计可执行实验方案的能力。含变量控制、对照设置、测量方案、仪器选型、误差来源预判、实验安全。可评级：1=能按指导书完成给定实验 2=能独立完成标准实验并记录 3=能改进现有实验方案 4=能针对新问题独立设计完整实验 5=能设计新实验方法或搭建新装置。', N'实验方案设计|实验方法设计|Experimental Design', NULL, N'物理学|应用物理学|核物理|声学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (199, N'数学建模', N'分析与设计方法', N'把现实或物理问题抽象为数学对象并求解的能力。含问题简化与假设、变量与参数选择、方程与模型构建、模型求解、结果检验与灵敏度分析。可评级：1=认识常见模型类型 2=能套用现成模型解标准题 3=能独立建立基础模型并求解 4=能建复杂模型并做验证与改进 5=能建模解决开放问题并指导他人。', N'数模|MCM|Mathematical Modeling', NULL, N'物理学|应用物理学|数学与应用数学|信息与计算科学|统计学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (200, N'实验数据处理', N'分析与设计方法', N'对实验测量数据进行整理、分析与不确定性评估的能力。含数据记录规范、异常值判别、误差传递、不确定度评定、曲线拟合、结果表达与图表规范。可评级：1=能规范记录原始数据 2=会算平均值与标准偏差 3=能用软件完成拟合与作图 4=能做误差传递与不确定度分析 5=能建立数据处理流程与规范。', N'实验数据分析|误差分析|不确定度评定|Data Processing', NULL, N'物理学|应用物理学|核物理|声学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (201, N'科研写作', N'表达与内容创作', N'按学术规范撰写研究报告与论文的能力。含文献综述、研究问题表述、方法与结果呈现、图表规范、引用与参考文献、投稿与同行评议应对。可评级：1=能写规范实验报告 2=能写课程论文 3=能写出可投稿的期刊论文初稿 4=能独立完成发表并回应审稿意见 5=能指导他人写作或担任审稿。', N'学术写作|论文写作|科技写作|Scientific Writing', NULL, N'物理学|应用物理学|数学与应用数学|化学|生物科学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (202, N'MATLAB', N'软件工具', N'面向数值计算与矩阵运算的科学计算环境。含矩阵运算、数据可视化、脚本与函数、工具箱（信号/图像/优化）、Simulink 仿真。可评级：1=掌握基本语法与矩阵操作 2=能绘图与写脚本 3=能写函数解决物理问题 4=能调用工具箱做仿真与建模 5=能优化性能并工程化部署。', N'Matlab|MATLAB语言', NULL, N'物理学|应用物理学|数学与应用数学|信息与计算科学');
INSERT INTO [dbo].[skills] ([skill_id], [skill_name], [skill_category], [skill_description], [alias_names], [parent_skill_id], [major_names]) VALUES (203, N'LaTeX', N'软件工具', N'面向长文档与公式排版的学术排版系统。含文档结构、数学公式、图表与交叉引用、参考文献（BibTeX）、模板与宏包定制。可评级：1=能用现成模板排版 2=能排版公式图表与目录 3=能独立完成论文排版 4=能自定义模板与宏包 5=能维护模板并培训他人。', N'TeX|LaTeX排版', NULL, N'物理学|应用物理学|数学与应用数学');
